from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            DataNormalizationMode.Raw,
            fillForward=False,
            extendedMarketHours=False
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_key = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.exit_ticket = None
        self.exit_order_id = None

        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            self._process_expiration_and_time_stop()
            self._process_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        if bar is None:
            return

        bar_time = bar.Time.astimezone(self.TimeZone)
        if not self._is_regular_session(bar_time):
            return

        bucket_key = (
            bar_time.date(),
            bar_time.hour,
            (bar_time.minute // 5) * 5
        )

        if self.bucket_key is not None and bucket_key != self.bucket_key:
            self._discard_incomplete_bucket()

        if self.bucket_key != bucket_key:
            self.bucket_key = bucket_key
            self.bucket_bars = {}

        self.bucket_bars[bar_time.minute] = bar

        if bar.EndTime.astimezone(self.TimeZone).minute % 5 != 0:
            return

        expected_minutes = set(range(bucket_key[2], bucket_key[2] + 5))
        if set(self.bucket_bars.keys()) != expected_minutes:
            self._discard_incomplete_bucket()
            return

        completed_close = self.bucket_bars[max(expected_minutes)].Close
        bar_end = bar.EndTime.astimezone(self.TimeZone)

        self._discard_incomplete_bucket()
        self._update_averages_and_check_entry(completed_close, bar_end, slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order_id is not None
                and order_event.OrderId == self.entry_order_id
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.entry_order_id = None

                self.Debug(
                    "ENTRY {} @ {:.2f}".format(
                        self.held_symbol.Value,
                        self.entry_price
                    )
                )

            elif (
                self.exit_order_id is not None
                and order_event.OrderId == self.exit_order_id
            ):
                self.Debug(
                    "EXIT {} @ {:.2f}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.exit_order_id = None

                if self.held_symbol == order_event.Symbol:
                    self.held_symbol = None
                    self.entry_price = None
                    self.no_entry_date = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None_
        ):
            if (
                self.entry_order_id is not None
                and order_event.OrderId == self.entry_order_id
            ):
                self.entry_ticket = None
                self.entry_order_id = None

            if (
                self.exit_order_id is not None
                and order_event.OrderId == self.exit_order_id
            ):
                self.exit_ticket = None
                self.exit_order_id = None

    def _is_regular_session(self, local_time):
        return (
            local_time.weekday() < 5
            and time(9, 30) <= local_time.time() < time(16, 0)
        )

    def _discard_incomplete_bucket(self):
        self.bucket_key = None
        self.bucket_bars = {}

    def _update_averages_and_check_entry(self, close, bar_end, slice):
        current_fast = None
        current_slow = None

        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0

        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.closes.append(float(close))

        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
        else:
            current_fast = None

        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0
        else:
            current_slow = None

        if bullish_crossover:
            if time(9, 45) <= bar_end.time() <= time(14, 30):
                self._try_enter(slice)
            else:
                self.Debug("Skipped crossover outside entry window")

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _try_enter(self, slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if (
            self.entry_ticket is not None
            and self.entry_order_id is not None
        ):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        eligible = []

        for contract in chain:
            expiry = contract.Symbol.ID.Date.date()

            if (
                contract.Right == OptionRight.Call
                and (expiry - today).days >= 7
            ):
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible expiration")
            return

        nearest_expiry = min(
            contract.Symbol.ID.Date.date()
            for contract in eligible
        )

        spy_price = slice.Bars[self.spy].Close
        target_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in eligible
            if (
                contract.Symbol.ID.Date.date() == nearest_expiry
                and contract.Strike >= target_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )
        self.entry_order_id = self.entry_ticket.OrderId

    def _process_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            return

        contract = None
        for candidate in chain:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.no_entry_date = today
            self._submit_exit("expiration protection")
            return

        prior_trading_day = self._previous_trading_day(expiry)

        if (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if exchange_hours.IsDateOpen(candidate_dt):
                return candidate
            candidate -= timedelta(days=1)

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None:
            self.entry_ticket.Cancel("Canceling entry before exit")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug("EXIT submitted: {}".format(reason))

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment; liquidating equity"
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

