    def _is_expiration_eve(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while True:
            candidate_dt = datetime(
                candidate.year, candidate.month, candidate.day
            )
            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate_dt):
