        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = self.spy_option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.previous_bucket = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_fill_quantity = 0
        self.entry_fill_value = 0

        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()

        self._process_spy_minute_bar(slice)

        self._evaluate_option_exit(slice)

        if (
            self.held_symbol is None
            and not self._entry_order_is_open()
            and self.blocked_entry_date != current_date
        ):
            self._try_enter(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return

        bar_start = bar.EndTime - timedelta(minutes=1)
        local_date = bar_start.date()
        minute = bar_start.hour * 60 + bar_start.minute

        regular_start = 9 * 60 + 30
        regular_end = 16 * 60

        if minute < regular_start or minute >= regular_end:
            return

        bucket_minute = regular_start + ((minute - regular_start) // 5) * 5
        bucket_key = (local_date, bucket_minute)

        if self.previous_bucket is not None and bucket_key != self.previous_bucket:
            self._complete_bucket(self.previous_bucket)

        self.bucket_bars[bucket_key] = bar
        self.previous_bucket = bucket_key

    def _complete_bucket(self, bucket_key):
        date_value, start_minute = bucket_key
        bars = []

        for offset in range(5):
            minute = start_minute + offset
            key = (date_value, minute)
            bar = self.bucket_bars.get(key)
            if bar is None:
                return
            bars.append(bar)

        close_bar = bars[-1]
        end_time = close_bar.EndTime
        close_price = close_bar.Close

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

        self.fast.Update(IndicatorDataPoint(self.spy_symbol, end_time, close_price))
        self.slow.Update(IndicatorDataPoint(self.spy_symbol, end_time, close_price))

        if (
            not self.fast.IsReady
            or not self.slow.IsReady
            or self.previous_fast is None
            or self.previous_slow is None
        ):
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_local = end_time
        if end_local.hour == 14 and end_local.minute == 30:
            eligible_time = True
        else:
            eligible_time = (
                (end_local.hour == 9 and end_local.minute >= 45)
                or (10 <= end_local.hour <= 13)
                or (end_local.hour == 14 and end_local.minute <= 30)
            )

        if bullish_cross and eligible_time:
            self.pending_entry_signal = True
        else:
            self.pending_entry_signal = False

    def _try_enter(self, slice: Slice):
        if not getattr(self, "pending_entry_signal", False):
            return

        self.pending_entry_signal = False

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None or spy_bar.Close <= 0:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = 1.01 * spy_bar.Close

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

