from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.expiration_block_date = None
        self.assignment_block_date = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

    def OnData(self, slice):
        self.current_slice = slice

        today = self.Time.date()

        if self.expiration_block_date == today or self.assignment_block_date == today:
            self.CancelOpenEntry()

        self.ProcessExpiration(today)
        self.EvaluateExit(slice, today)

        if (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity == 0
            and not self.IsEntryOrderOpen()
            and not self.IsExitOrderOpen()
        ):
            self.held_symbol = None
            self.entry_price = None

        self.consolidator.Update(slice)

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime.time()

        # Only use regular-session five-minute bars.
        if end_time < time(9, 35) or end_time > time(16, 0):
            return

        if self.closes.IsReady:
            previous_fast = sum(
                [self.closes[i] for i in range(self.fast_period)]
            ) / self.fast_period
            previous_slow = sum(
                [self.closes[i] for i in range(self.slow_period)]
            ) / self.slow_period
        else:
            previous_fast = None
            previous_slow = None

        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(
            [self.closes[i] for i in range(self.fast_period)]
        ) / self.fast_period
        current_slow = sum(
            [self.closes[i] for i in range(self.slow_period)]
        ) / self.slow_period

        eligible_time = time(9, 45) <= end_time <= time(14, 30)
        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_crossover:
            self.TryEnterCall()

    def TryEnterCall(self):
        today = self.Time.date()

        if (
            self.expiration_block_date == today
            or self.assignment_block_date == today
            or self.held_symbol is not None
            or self.IsEntryOrderOpen()
        ):
            return

        if self.current_slice is None:
            self.Debug("Skipped entry: current Slice unavailable.")
            return

        try:
            chains = list(self.current_slice.OptionChains.Values)
            if len(chains) == 0:
                self.Debug("Skipped entry: no option chain.")
                return

            min_expiration = today + timedelta(days=7)
            contracts = []

            for chain in chains:
                for contract in chain:
                    expiry = contract.Expiry.date()
                    if expiry >= min_expiration:
                        contracts.append(contract)

            if len(contracts) == 0:
                self.Debug("Skipped entry: no expiration at least 7 days out.")
                return

            selected_expiration = min(
                contract.Expiry.date() for contract in contracts
            )

            spy_price = float(self.Securities[self.spy.Symbol].Price)
            if spy_price <= 0:
                self.Debug("Skipped entry: invalid SPY price.")
                return

            candidates = [
                contract
                for contract in contracts
                if contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= 1.01 * spy_price
            ]

            if len(candidates) == 0:
                self.Debug("Skipped entry: no qualifying call at nearest expiration.")
                return

            selected = sorted(
                candidates,
                key=lambda contract: (contract.Strike, str(contract.Symbol))
            )[0]

            self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

            self.Debug(
                "Entry submitted: {0}, expiration {1}, strike {2:.2f}".format(
                    selected.Symbol,
                    selected_expiration,
                    selected.Strike,
                )
            )

        except Exception:
            self.Debug("Skipped entry: option selection failed.")

    def EvaluateExit(self, slice, today):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry = self.held_symbol.ID.Date.date()
        prior_trading_day = self.PreviousTradingDay(expiry)

        time_stop = (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        )

        midpoint = self.CurrentOptionMidpoint(slice, self.held_symbol)
        profit_target = (
            midpoint is not None
            and midpoint >= 1.50 * self.entry_price
        )

        if profit_target:
            self.SubmitExit("profit target")
        elif time_stop:
            self.SubmitExit("pre-expiration time stop")

    def CurrentOptionMidpoint(self, slice, symbol):
        try:
            for chain in slice.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == symbol:
                        bid = float(contract.BidPrice)
                        ask = float(contract.AskPrice)
                        if bid > 0 and ask > 0:
                            return (bid + ask) / 2.0
                        return None
        except Exception:
            return None

        return None

    def ProcessExpiration(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if today >= expiry:
            self.expiration_block_date = today
            self.CancelOpenEntry()
            self.SubmitExit("expiration protection")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.IsExitOrderOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.CancelOpenExit()
        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: {0} ({1}).".format(self.held_symbol, reason))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.AverageFillPrice)
                self.Debug(
                    "Entry filled: {0} at {1:.4f}.".format(
                        order_event.Symbol,
                        self.entry_price,
                    )
                )

            if order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled,
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}.".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ]:
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_event):
        self.HandleUnexpectedOptionEvent("assignment")

    def OnExerciseOrder(self, exercise_event):
        self.HandleUnexpectedOptionEvent("exercise")

    def HandleUnexpectedOptionEvent(self, event_name):
        today = self.Time.date()
        self.assignment_block_date = today
        self.expiration_block_date = today
        self.Debug("Unexpected option {0}; liquidating SPY equity.".format(event_name))

        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy.Symbol, -quantity)

    def PreviousTradingDay(self, date_value):
        date_value -= timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)
        return date_value

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ]
        )

    def IsExitOrderOpen(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ]
        )

    def CancelOpenEntry(self):
        if self.IsEntryOrderOpen():
            self.entry_ticket.Cancel("Entry blocked.")
        self.entry_ticket = None

    def CancelOpenExit(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replacing exit order.")
        self.exit_ticket = None


