        local_time = self.TimeZone.ConvertFromUtc(minute_bar.End)
        local_start = local_time.replace(second=0, microsecond=0)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        bucket_minute = (local_start.minute // 5) * 5
        bucket_start = local_start.replace(minute=bucket_minute)

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
        elif bucket_start != self.current_bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[local_start] = minute_bar

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if local_start != expected_times[-1]:
            return

        if any(t not in self.current_bucket_bars for t in expected_times):
            self.current_bucket_bars = {}
            return

        bars = [self.current_bucket_bars[t] for t in expected_times]
        five_minute_close = bars[-1].Close
        five_minute_end = self.current_bucket_start + timedelta(minutes=5)

        self.current_bucket_bars = {}
        self._process_five_minute_bar(five_minute_end, five_minute_close, slice)

    def _process_five_minute_bar(self, bar_end, close, slice):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        if not (previous_fast <= previous_slow and current_fast > current_slow):
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        eligible_expiries = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    eligible_expiries.append(expiry_date)

        if not eligible_expiries:
            self.Debug("Skipped call selection: no eligible expiration")
            return

        selected_expiry = min(eligible_expiries)
        minimum_strike = float(spy_price) * 1.01
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Expiry.date() == selected_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_fill_quantity = 0
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_held_position(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        held_contract = None
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self.held_symbol):
                held_contract = chain.Contracts[self.held_symbol]
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _handle_expiration_processing(self, slice):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if expiry_date <= current_date:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")

    def _submit_time_stop_if_due(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)

        while not self._is_spy_trading_day(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted (" + reason + "): " + str(self.held_symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                fill_quantity = abs(order_event.FillQuantity)
                if fill_quantity > 0:
                    prior_quantity = self.entry_fill_quantity
                    self.entry_price = (
                        (
                            (self.entry_price or 0.0) * prior_quantity
                            + float(order_event.FillPrice) * fill_quantity
                        )
                        / (prior_quantity + fill_quantity)
                    )
                    self.entry_fill_quantity += fill_quantity
                    self.held_symbol = order_event.Symbol
                    self.Debug(
                        "Entry filled: "
                        + str(order_event.Symbol)
                        + " @ "
                        + str(order_event.FillPrice)
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.entry_ticket = None
                self.entry_price = None
                self.entry_fill_quantity = 0

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: "
                + str(order_event.Symbol)
                + " @ "
                + str(order_event.FillPrice)
            )
            self.exit_ticket = None
            self.entry_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_fill_quantity = 0

    def OnEndOfDay(self, symbol):
        self._submit_time_stop_if_due()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        current_date = self.Time.date()
        if self.assignment_handled_date != current_date:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
            self.assignment_handled_date = current_date
            self.blocked_entry_date = current_date

        self.MarketOrder(self.spy_symbol, -quantity)

    def _is_spy_trading_day(self, date_value):
        date_time = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        return self.spy.Exchange.Hours.IsDateOpen(date_time)

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

