            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted (" + reason + "): " + str(self.held_symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                fill_quantity = abs(order_event.FillQuantity)
                if fill_quantity > 0:
                    prior_quantity = self.entry_fill_quantity
                    self.entry_price = (
                        (
                            (self.entry_price or 0.0) * prior_quantity
                            + float(order_event.FillPrice) * fill_quantity
                        )
                        / (prior_quantity + fill_quantity)
                    )
                    self.entry_fill_quantity += fill_quantity
                    self.held_symbol = order_event.Symbol
                    self.Debug(
                        "Entry filled: "
                        + str(order_event.Symbol)
                        + " @ "
                        + str(order_event.FillPrice)
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.entry_ticket = None
                self.entry_price = None
                self.entry_fill_quantity = 0

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: "
                + str(order_event.Symbol)
                + " @ "
                + str(order_event.FillPrice)
            )
            self.exit_ticket = None
            self.entry_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_fill_quantity = 0

    def OnEndOfDay(self, symbol):
        self._submit_time_stop_if_due()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        current_date = self.Time.date()
        if self.assignment_handled_date != current_date:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
            self.assignment_handled_date = current_date
            self.blocked_entry_date = current_date

