    def _is_spy_trading_day(self, date_value):
        date_time = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        return self.spy.Exchange.Hours.IsDateOpen(date_time)

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

