        if (
            self._is_immediately_preceding_trading_day(current_date, expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain.Contracts.Values:
            if contract.Symbol == self._held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.Securities[self._held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self._no_entry_today = True
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self._exit_ticket.OrderId)

        quantity = -int(holding.Quantity)
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(self._held_symbol, quantity)
        self.Debug("Exit submitted: {}".format(reason))

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self._no_entry_today = True
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.MarketOrder(self.spy, -int(holding.Quantity))

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while candidate > current_date:
            if exchange_hours.IsDateOpen(candidate):
                return current_date == candidate
            candidate -= timedelta(days=1)

        return current_date == candidate

