        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda u: u.IncludeWeeklys().Strikes(-500, 500).Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_dates = set()
        self.time_stop_dates = set()
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        self.current_slice = slice

        self._handle_unexpected_spy_position()
        self._process_expiration()
        self._process_option_exit()

        if self.spy in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy])

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.Time
        current_date = local_time.date()
        minute_of_day = local_time.hour * 60 + local_time.minute

        if minute_of_day < 570 or minute_of_day >= 960:
            return

        bucket_minute = 570 + ((minute_of_day - 570) // 5) * 5
        bucket_start = time(bucket_minute // 60, bucket_minute % 60)

        if (
            self.bucket_date != current_date
            or self.bucket_start != bucket_start
        ):
            self._finalize_bucket()

            self.bucket_date = current_date
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        minute_key = minute_bar.Time.replace(second=0, microsecond=0)
        self.bucket_bars[minute_key] = minute_bar

    def _finalize_bucket(self):
        if not self.bucket_bars or self.bucket_date is None:
            return

        expected_start = datetime.combine(
            self.bucket_date, self.bucket_start
        )
        expected_times = [
            expected_start + timedelta(minutes=i) for i in range(5)
        ]

        if any(t not in self.bucket_bars for t in expected_times):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = expected_start + timedelta(minutes=5)

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) >= 5 and len(self.slow_values) >= 20:
            fast = sum(list(self.fast_values)[-5:]) / 5.0
            slow = sum(self.slow_values) / 20.0

            bullish_cross = (
                self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and fast > slow
            )

            self.previous_fast = fast
            self.previous_slow = slow

            end_time = bar_end.time()
            eligible = (
                time(9, 45) <= end_time <= time(14, 30)
            )

            if bullish_cross and eligible:
                self._try_enter()

        self.bucket_bars = {}

    def _try_enter(self):
        current_date = self.Time.date()

        if current_date in self.blocked_entry_dates:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                          OrderStatus.PartiallyFilled):
                return

        price = self.Securities[self.spy].Price
        if price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chain = None
        try:
            chain = self.current_slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        try:
            contracts = list(chain.Contracts.Values)
        except Exception:
            contracts = list(chain.Contracts.values())

        minimum_expiry = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        expiry_date = expirations[0]
        minimum_strike = 1.01 * price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry_date
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiry {} strike {:.2f}".format(
                selected.Symbol, expiry_date, selected.Strike
            )
        )

    def _process_option_exit(self):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        contract = None
        try:
            chain = self.current_slice.OptionChains.get(self.option_symbol)
            if chain is not None:
                try:
                    contracts = chain.Contracts.Values
                except Exception:
                    contracts = chain.Contracts.values()

                for candidate in contracts:
                    if candidate.Symbol == self.held_symbol:
                        contract = candidate
                        break
        except Exception:
            contract = None

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.blocked_entry_dates.add(current_date)
            if self.Portfolio[self.held_symbol].Quantity > 0:
                self._submit_exit("expiration protection")
            return

        prior_trading_date = expiry_date - timedelta(days=1)
        while prior_trading_date.weekday() >= 5:
            prior_trading_date -= timedelta(days=1)

        if (
            current_date == prior_trading_date
            and self.Time.time() >= time(15, 45)
            and current_date not in self.time_stop_dates
        ):
            self.time_stop_dates.add(current_date)
            if self.Portfolio[self.held_symbol].Quantity > 0:
                self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                          OrderStatus.PartiallyFilled):
                return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                          OrderStatus.PartiallyFilled):
                return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            try:
                self.exit_ticket.Cancel("Replacing exit order")
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity, tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_symbol, reason))

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if not self.equity_liquidation_submitted:
                self.equity_liquidation_submitted = True
                self.Debug(
                    "Unexpected SPY exercise/assignment position; liquidating"
                )
                self.MarketOrder(self.spy, -quantity, tag="Unexpected assignment")
        else:
            self.equity_liquidation_submitted = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Exit filled: {} at {:.4f}".format(
                    order_event.Symbol, order_event.FillPrice
                ))
                self.exit_ticket = None
                if self.held_symbol == order_event.Symbol:
                    self.held_symbol = None
                    self.entry_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.Debug("Entry order did not fill")
                self.entry_ticket = None

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_event: AssignmentOrderEvent):
        self.Debug("Unexpected option exercise or assignment received")
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy, -quantity, tag="Unexpected exercise or assignment"
            )

