from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False
        )
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 400)
        )
        self.option_canonical = option.Symbol

        self.bucket_start = None
        self.bucket_bars = {}

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.held_option = None
        self.entry_price = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.assignment_liquidation_ticket = None

    def OnData(self, slice: Slice):
        algorithm_date = self.Time.date()

        self._handle_unexpected_spy_position(algorithm_date)
        self._handle_expiration(algorithm_date)
        self._evaluate_option_exit(slice, algorithm_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._update_five_minute_bar(spy_bar)
        if consolidated is None:
            return

        fast = None
        slow = None
        if len(self.closes) >= 5:
            fast = sum(self.closes[-5:]) / 5.0
        if len(self.closes) >= 20:
            slow = sum(self.closes[-20:]) / 20.0

        if fast is None or slow is None:
            return

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end = consolidated.EndTime
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow

        if (
            bullish_cross
            and eligible_time
            and self.no_entry_date != algorithm_date
            and self.held_option is None
            and self._entry_order_is_open()
        ):
            self._select_and_enter(slice, spy_bar.Close)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime
        current_date = end_time.date()
        current_time = end_time.time()

        if current_time <= time(9, 30) or current_time > time(16, 0):
            return None

        session_start = datetime.combine(current_date, time(9, 30))
        elapsed_minutes = int((end_time - session_start).total_seconds() / 60)

        if elapsed_minutes <= 0:
            return None

        bucket_index = (elapsed_minutes - 1) // 5
        bucket_start = session_start + timedelta(minutes=5 * bucket_index)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[end_time] = minute_bar

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if end_time != expected_times[-1]:
            return None

        valid = (
            len(self.bucket_bars) == 5
            and all(expected in self.bucket_bars for expected in expected_times)
        )

        bars = self.bucket_bars
        self.bucket_bars = {}

        if not valid:
            return None

        consolidated = TradeBar(
            bucket_start,
            self.spy,
            bars[expected_times[0]].Open,
            max(b.High for b in bars.values()),
            min(b.Low for b in bars.values()),
            bars[expected_times[-1]].Close,
            sum(b.Volume for b in bars.values()),
            timedelta(minutes=5)
        )

        self.closes.append(float(consolidated.Close))
        return consolidated

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return True

        status = self.entry_ticket.Status
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= float(spy_price) * 1.01
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        same_expiry = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
        ]

        selected = min(
            same_expiry,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {} strike {}".format(
                selected.Symbol,
                nearest_expiry,
                selected.Strike
            )
        )

    def _evaluate_option_exit(self, slice: Slice, algorithm_date):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        time_stop = (
            algorithm_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

        if time_stop:
            self._submit_exit("expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = slice.OptionChains.get(self.option_canonical)
        if contract is None:
            for chain in slice.OptionChains.Values:
                if any(c.Symbol == self.held_option for c in chain.Contracts.Values):
                    contract = chain
                    break

        if contract is None:
            return

        held_contract = None
        for item in contract.Contracts.Values:
            if item.Symbol == self.held_option:
                held_contract = item
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = int(holding.Quantity)

        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}.".format(reason))

    def _handle_expiration(self, algorithm_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if algorithm_date >= expiry_date:
            self.no_entry_date = algorithm_date
            self._submit_exit("expiration protection")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        try:
            while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime.combine(candidate, time(0, 0))
            ):
                candidate -= timedelta(days=1)
                while candidate.weekday() >= 5:
                    candidate -= timedelta(days=1)
        except Exception:
            pass

        return candidate

    def _handle_unexpected_spy_position(self, algorithm_date):
        quantity = int(self.Portfolio[self.spy].Quantity)
        if quantity == 0:
            return

        self.no_entry_date = algorithm_date

        if self.assignment_liquidation_ticket is None:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="unexpected exercise or assignment"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment received.")
            self._handle_unexpected_spy_position(self.Time.date())

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}.".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.assignment_liquidation_ticket is not None
            and order_event.OrderId
            == self.assignment_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("SPY assignment liquidation filled.")
            self.assignment_liquidation_ticket = None.rstrip() if False else None

