        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self.current_bucket_end = None
        self.current_bucket_bars = {}
        self.current_bucket_close = None

        self.held_symbol = None
        self.entry_price = None
        self.entry_order = None
        self.exit_order = None

        self.blocked_entry_date = None
        self.time_stop_processed = set()

    def OnData(self, data: Slice):
        self._handle_equity_created_by_exercise_or_assignment()
        self._manage_held_option(data)
        self._process_spy_minute_bar(data)

    def _process_spy_minute_bar(self, data: Slice):
        if self.spy not in data.Bars:
            return

        bar = data.Bars[self.spy]
        bar_time = bar.Time
        bar_date = bar_time.date()
        bar_minutes = bar_time.hour * 60 + bar_time.minute

        # Regular session only: 09:30 through 16:00 New York time.
        if bar_minutes < 570 or bar_minutes >= 960:
            return

        bucket_end_minutes = ((bar_minutes - 570) // 5 + 1) * 5 + 570
        bucket_end_hour = bucket_end_minutes // 60
        bucket_end_minute = bucket_end_minutes % 60
        bucket_end = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            bucket_end_hour,
            bucket_end_minute,
        )

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._discard_incomplete_bucket()
            self.current_bucket_end = bucket_end

        self.current_bucket_bars[bar_time] = bar
        self.current_bucket_close = bar.Close

        if bar_time.minute == 34 or bucket_end == bar.EndTime:
            if len(self.current_bucket_bars) == 5:
                self._process_completed_five_minute_bar(
                    self.current_bucket_end,
                    self.current_bucket_close,
                )
            self.current_bucket_bars = {}
            self.current_bucket_close = None
            self.current_bucket_end = None

    def _discard_incomplete_bucket(self):
        self.current_bucket_bars = {}
        self.current_bucket_close = None

    def _process_completed_five_minute_bar(self, bar_end, close):
        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) == 5:
            previous_fast = sum(self.fast_closes) / 5.0
        if len(self.slow_closes) == 20:
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = (
            (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45))
            and (bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30))
        )

        if bullish_crossover and eligible_time:
            self._attempt_entry()

    def _attempt_entry(self):
