        candidates = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        current_price = self.Securities[self.spy.Symbol].Price

        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * current_price
        strike_candidates = [
            contract
            for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol)),
        )

        self.entry_order = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry",
        )

    def _manage_held_option(self, data: Slice):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_option_exit("Expiration protection")
            return

        prior_trading_day = self._previous_trading_day(expiry_date)
        current_time = self.Time.time()

        if (
            current_date == prior_trading_day
            and current_time.hour == 15
            and current_time.minute >= 45
            and current_date not in self.time_stop_processed
        ):
            self.time_stop_processed.add(current_date)
            self._submit_option_exit("Pre-expiration time stop")
            return

        if self._exit_order_is_open():
            return

        contract = self._find_held_contract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        if self.entry_price is not None:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._cancel_open_exit_order()
                self._submit_option_exit("50% profit target")

    def _find_held_contract(self, data: Slice):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def _submit_option_exit(self, tag):
        if self.held_symbol is None or self._exit_order_is_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity > 0:
            self.exit_order = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=tag,
            )

    def _cancel_open_exit_order(self):
        if self._exit_order_is_open():
            self.exit_order.Cancel("Replaced by profit-target exit")

    def _entry_order_is_open(self):
        if self.entry_order is None:
            return False

        return self.entry_order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _exit_order_is_open(self):
        if self.exit_order is None:
            return False

        return self.exit_order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_equity_created_by_exercise_or_assignment(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation",
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order is not None and order_event.OrderId == self.entry_order.OrderId:
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled,
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice

                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = self.entry_order.AverageFillPrice
                    self.entry_order = None
                    self.Debug(
                        "Entered {} at {:.2f}".format(
                            self.held_symbol,
                            self.entry_price,
                        )
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_order = None

        if self.exit_order is not None and order_event.OrderId == self.exit_order.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited {} at {:.2f}".format(
                        order_event.Symbol,
                        order_event.FillPrice,
                    )
                )

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_order = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_order = None

        message = str(getattr(order_event, "Message", "")).lower()
        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = "exercise" in message or "assignment" in message

        if is_assignment or is_exercise:
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_equity_created_by_exercise_or_assignment()

