        self._handle_expiration_processing()
        self._evaluate_minute_exit(slice)

        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy])

    def _process_minute_bar(self, bar: TradeBar):
        local_time = bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ) or local_time.hour >= 16:
            return

        bucket_minute = 30 + ((local_time.minute - 30) // 5) * 5
        bucket_start = local_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_five_minute_bar()
            self.bucket_start = bucket_start
            self.bucket_closes = []

        self.bucket_closes.append(float(bar.Close))

    def _complete_five_minute_bar(self):
        if self.bucket_start is None:
            return

        closes = self.bucket_closes
        self.bucket_closes = []

        if len(closes) != 5:
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(self.bucket_start + timedelta(minutes=5), closes[-1])
        self.slow.Update(self.bucket_start + timedelta(minutes=5), closes[-1])

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bar_end = self.bucket_start + timedelta(minutes=5)
        end_time = bar_end.time()

        eligible_time = (
            time(9, 45) <= end_time <= time(14, 30)
        )
        bullish_crossover = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_crossover:
            self._try_enter(closes[-1], bar_end.date())

    def _try_enter(self, spy_price: float, algorithm_date):
        if self.expiration_block_date == algorithm_date:
            return

        if self.selected_symbol is not None:
            holding = self.Portfolio[self.selected_symbol]
            if holding.Invested:
                return

        if self.entry_ticket is not None and not self._ticket_closed(self.entry_ticket):
            return

        if self.current_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in self.current_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        expiration = expirations[0]
        threshold = spy_price * 1.01

        candidates = [
            contract for contract in self.current_chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = candidates[0]

        self.selected_symbol = contract.Symbol
        self.expiration_date = expiration
        self.expiration_block_date = expiration

        try:
            self.pre_expiration_date = (
                self.Securities[self.spy].Exchange.Hours
                .GetPreviousTradingDay(contract.Expiry)
                .date()
            )
        except Exception:
            self.pre_expiration_date = expiration - timedelta(days=1)

        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.selected_symbol,
            1,
            tag="Bullish SPY call entry"
        )
        self.Debug(f"Entry submitted: {self.selected_symbol}")

    def _evaluate_minute_exit(self, slice: Slice):
        symbol = self.selected_symbol
        if symbol is None or not self.Portfolio[symbol].Invested:
            return

        current_date = self.Time.date()
        current_time = self.Time.time()

        if (
            self.pre_expiration_date == current_date
            and current_time >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        contract = self._find_current_contract(slice, symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        if self.entry_price is not None:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self._submit_exit("50% profit target")

    def _find_current_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason: str):
        if self.exit_ticket is not None and not self._ticket_closed(self.exit_ticket):
            return

        if self.selected_symbol is None:
            return

        quantity = self.Portfolio[self.selected_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(
            self.selected_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _handle_expiration_processing(self):
        if self.selected_symbol is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.selected_symbol].Invested:
                self._submit_exit("Expiration protection")

    def _handle_unexpected_spy_position(self):
        if self.spy not in self.Portfolio:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.spy_cleanup_ticket is not None and
            not self._ticket_closed(self.spy_cleanup_ticket)
        ):
            return

        self.Debug("Unexpected exercise or assignment: liquidating SPY.")
        self.spy_cleanup_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            return

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.FillQuantity > 0
        ):
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"Entry filled: {self.selected_symbol} "
                f"at {self.entry_price:.4f}"
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {self.selected_symbol}")
            self.exit_ticket = None
            self.entry_ticket = None
            self.selected_symbol = None
            self.expiration_date = None
            self.pre_expiration_date = None
            self.entry_price = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment processed.")
            self._handle_unexpected_spy_position()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment processed.")
        self._handle_unexpected_spy_position()

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and not self._ticket_closed(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit")

    @staticmethod
    def _ticket_closed(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

