from AlgorithmImports import *
from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol
        self.spy_security = equity

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

        self.bucket_start = None
        self.bucket_bars = {}

    def OnData(self, slice):
        now = self.Time
        current_date = now.date()

        self._handle_unexpected_spy_position()
        self._process_expiration(now)

        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_exit(slice, now)

        if not self._has_open_entry_order() and not self._has_option_position():
            self._process_spy_bar(slice)

    def _process_spy_bar(self, slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        bar_time = bar.Time
        bar_end = bar.EndTime

        if bar_time.date() != bar_end.date():
            return

        local_time = bar_time.time()
        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute = bar_time.replace(second=0, microsecond=0)
        bucket_minute = minute.minute - (minute.minute % 5)
        bucket_start = minute.replace(minute=bucket_minute)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_start is not None and (
            bucket_start.date() != self.bucket_start.date()
            or bucket_start != self.bucket_start
        ):
            self._finalize_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[minute] = bar

    def _finalize_bucket(self):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected):
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected]
        close = bars[-1].Close
        bar_end = self.bucket_start + timedelta(minutes=5)

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = float(self.fast.Current.Value) if previous_ready else None
        previous_slow = float(self.slow.Current.Value) if previous_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        bullish_cross = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        if bullish_cross and eligible_time:
            self._try_enter(bar_end.date())

        self.bucket_start = None
        self.bucket_bars = {}

    def _try_enter(self, algorithm_date):
        if self.no_entry_date == algorithm_date:
            return

        if self._has_open_entry_order() or self._has_option_position():
            return

        current_price = float(self.spy_security.Price)
        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chains = list(self.CurrentSlice.OptionChains)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= current_price * 1.01
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiring {}".format(
                selected.Symbol,
                nearest_expiry
            )
        )

    def _evaluate_exit(self, slice, now):
        expiry_date = self._held_expiry_date()
        if expiry_date is None:
            return

        if now.date() == self._preceding_trading_day(expiry_date):
            if now.time() >= time(15, 45):
                self._submit_exit("Expiration-eve time stop")
                return

        contract = self._get_current_contract(slice, self.held_symbol)
        if contract is None:
            return

