        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_exit(slice, now)

        if not self._has_open_entry_order() and not self._has_option_position():
            self._process_spy_bar(slice)

    def _process_spy_bar(self, slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        bar_time = bar.Time
        bar_end = bar.EndTime

        if bar_time.date() != bar_end.date():
            return

        local_time = bar_time.time()
        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute = bar_time.replace(second=0, microsecond=0)
        bucket_minute = minute.minute - (minute.minute % 5)
        bucket_start = minute.replace(minute=bucket_minute)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_start is not None and (
            bucket_start.date() != self.bucket_start.date()
            or bucket_start != self.bucket_start
        ):
            self._finalize_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[minute] = bar

    def _finalize_bucket(self):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected):
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected]
        close = bars[-1].Close
        bar_end = self.bucket_start + timedelta(minutes=5)

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = float(self.fast.Current.Value) if previous_ready else None
        previous_slow = float(self.slow.Current.Value) if previous_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        bullish_cross = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        if bullish_cross and eligible_time:
            self._try_enter(bar_end.date())

        self.bucket_start = None
        self.bucket_bars = {}

