from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=365))
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None
        self.last_assignment_check_date = None

    def OnData(self, data: Slice):
        # Assignment or exercise should never leave an SPY equity position open.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment handling: liquidating SPY equity position."
            )
            self.MarketOrder(self.spy, -spy_quantity)
            self.expiration_block_date = self.Time.date()

        # Expiration-day liquidation takes precedence over all strategy activity.
        if self.held_symbol is not None:
            expiration_date = self.held_symbol.ID.Date.date()
            if self.Time.date() >= expiration_date:
                self.expiration_block_date = self.Time.date()
                self._submit_exit("expiration liquidation")
            elif (
                self.Time.date() == expiration_date - timedelta(days=1)
                and self.Time.hour == 15
                and self.Time.minute == 45
            ):
                self._submit_exit("pre-expiration time stop")

        # Feed only actual minute TradeBars into the five-minute consolidator.
        if data.Bars.ContainsKey(self.spy):
            self.consolidator.Update(data.Bars[self.spy])

        # The pending signal is consumed exactly once.
        if self.pending_signal:
            self.pending_signal = False

            if self.expiration_block_date == self.Time.date():
                return

            if self.held_symbol is not None:
                return

            if self._entry_order_open():
                return

            self._try_enter(data)

        self._evaluate_profit_target(data)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end = bar.EndTime
        if bullish_cross and (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        ):
            self.pending_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def _try_enter(self, data: Slice):
        if self.option.Symbol not in data.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = data.OptionChains[self.option.Symbol]
        algorithm_date = self.Time.date()
        minimum_expiration = algorithm_date + timedelta(days=7)

        eligible = []
        for contract in chain:
            expiration_date = contract.Expiry.date()
            if (
                contract.Right == OptionRight.Call
                and expiration_date >= minimum_expiration
            ):
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        nearest_expiration = min(contract.Expiry.date() for contract in eligible)
        price = self.Securities[self.spy].Price

        if price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiration
            and contract.Strike >= 1.01 * price
        ]

        if not candidates:
            self.Debug("Skipped entry: no call meets the strike rule.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_profit_target(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        current_contract = None
        if self.option.Symbol in data.OptionChains:
            for contract in data.OptionChains[self.option.Symbol]:
                if contract.Symbol == self.held_symbol:
                    current_contract = contract
                    break

        if current_contract is None:
            return

        bid = current_contract.BidPrice
        ask = current_contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted (" + reason + "): " + str(self.held_symbol))

    def _entry_order_open(self):
        return self.entry_ticket is not None and self._ticket_open(self.entry_ticket)

    @staticmethod
    def _ticket_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: "
                    + str(order_event.Symbol)
                    + " @ "
                    + str(order_event.FillPrice)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_ticket = None

