        self._process_expiration_state(current_date)

        if not slice.Bars.ContainsKey(self.spy):
            self._evaluate_held_option(slice, current_date, current_time)
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice, current_date, current_time)
        self._evaluate_held_option(slice, current_date, current_time)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice,
                            current_date, current_time):
        bar_end = self.Time
        if bar_end.date() != current_date:
            return

        if current_time < time(9, 31) or current_time > time(16, 0):
            return

        minutes_since_open = (
            current_time.hour * 60 + current_time.minute
        ) - (9 * 60 + 30)

        bucket_index = (minutes_since_open - 1) // 5
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            9,
            30
        ) + timedelta(minutes=bucket_index * 5)

        if self.bucket_date != current_date:
            self.bucket_date = current_date
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        elif bucket_start != self.bucket_start:
            self._complete_bucket(slice, self.bucket_start)
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        self.bucket_closes[current_time] = bar.Close

    def _complete_bucket(self, slice: Slice, bucket_start):
        expected_times = [
            (bucket_start + timedelta(minutes=i)).time()
            for i in range(1, 6)
        ]

        if not all(t in self.bucket_closes for t in expected_times):
            return

        close = self.bucket_closes[expected_times[-1]]
        bar_end_time = bucket_start + timedelta(minutes=5)

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

