            return

        self._try_entry(slice, close, bar_end_time.date())

    def _try_entry(self, slice: Slice, spy_price: float, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Quantity != 0:
                return

        if self.entry_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
            if ticket is not None and self._is_open(ticket):
                return

        chains = []
        if slice.OptionChains:
            chains = list(slice.OptionChains.Values)

        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no expiration at least 7 days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.held_symbol = selected.Symbol
        self.entry_price = None
        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute crossover entry"
        )
        self.entry_order_id = ticket.OrderId

    def _evaluate_held_option(self, slice: Slice, current_date, current_time):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date == self._previous_trading_day(expiry_date):
            if current_time >= time(15, 45):
                self._submit_exit("Expiration-eve time stop")
                return

        if self.entry_price is None:
            return

        contract = None
        if slice.OptionChains:
            for chain in slice.OptionChains.Values:
                for candidate in chain:
                    if candidate.Symbol == self.held_symbol:
                        contract = candidate
                        break
                if contract is not None:
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _process_expiration_state(self, current_date):
        self.no_entry_date = None

        if self.entry_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
            if ticket is not None and self._is_open(ticket):
                symbol = self.Securities[ticket.Symbol].Symbol
                expiry_date = symbol.ID.Date.date()
                if current_date >= expiry_date:
                    ticket.Cancel("Expiration processing")
                    self.no_entry_date = current_date

        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("Expiration processing")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            existing = self.Transactions.GetOrderTicket(self.exit_order_id)
            if existing is not None and self._is_open(existing):
                return

        ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            reason
        )
        self.exit_order_id = ticket.OrderId

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.Debug:
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")

        self.MarketOrder(
            self.spy,
            -quantity,
            "Unexpected exercise or assignment cleanup"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ):
                if order_event.FillPrice > 0 and self.entry_price is None:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entered {} at {:.4f}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited {}: {}".format(
                        self.held_symbol,
                        order_event.Message
                    )
                )
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

    def _is_open(self, ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

