from datetime import timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol,
            self.consolidator
        )

        self.latest_slice = None
        self.pending_signal = None
        self.last_consolidated_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_guard_date = None
        self.no_entry_date = None
        self.spy_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime
        end_clock = end_time.time()

        # Regular-session five-minute bars only.
        if end_clock < time(9, 35) or end_clock > time(16, 0):
            return

        if self.last_consolidated_end == end_time:
            return

        self.last_consolidated_end = end_time

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        # Only actual consolidated bars update the indicators.
        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        eligible_time = time(9, 45) <= end_clock <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_cross:
            self.pending_signal = {
                "time": end_time,
                "price": float(bar.Close)
            }

    def OnData(self, slice):
        self.latest_slice = slice
        current_date = self.Time.date()

        self.HandleUnexpectedSpyPosition(current_date)

        # Never intentionally carry an option into expiration.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if current_date >= expiration_date:
                self.no_entry_date = current_date
                self.expiration_guard_date = current_date
                self.SubmitOptionExit("expiration protection")
            elif self.IsImmediatelyPrecedingTradingDay(
                current_date,
                expiration_date
            ) and self.Time.time() >= time(15, 45):
                self.SubmitOptionExit("pre-expiration time stop")

            self.EvaluateProfitTarget(slice)

        if self.pending_signal is not None:
            signal = self.pending_signal
            self.pending_signal = None
            self.TryEnter(slice, signal["price"], signal["time"])

    def TryEnter(self, slice, spy_price, signal_time):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[
            self.held_option
        ].Invested:
            return

        if self.entry_ticket is not None and self.IsOpen(
            self.entry_ticket.Status
        ):
            return

        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            self.Debug(
                f"{self.Time}: skipped entry; no option chain in current Slice"
            )
            return

        algorithm_date = self.Time.date()
        minimum_expiration = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug(
                f"{self.Time}: skipped entry; no expiration at least 7 "
                "calendar days away"
            )
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call at "
                f"{selected_expiration}"
            )
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"{self.Time}: entry submitted for {selected.Symbol}; "
            f"expiration {selected_expiration}, strike {selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOpen(
            self.exit_ticket.Status
        ):
            return

        contract = self.GetHeldContract(slice)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("50% profit target")

    def SubmitOptionExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self.IsOpen(
            self.exit_ticket.Status
        ):
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            f"{self.Time}: option exit submitted for {self.held_option}; "
            f"reason: {reason}"
        )

    def OnOrderEvent(self, order_event):
        symbol = order_event.Symbol
        status = order_event.Status

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"{self.Time}: unexpected option exercise or assignment "
                f"for {symbol}"
            )
            self.HandleUnexpectedSpyPosition(self.Time.date())

        if (
            self.entry_ticket is not None and
            symbol == self.entry_ticket.Symbol
        ):
            if status == OrderStatus.Filled:
                self.held_option = symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: option entry filled for {symbol} at "
                    f"{self.entry_price}"
                )
            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            symbol == self.exit_ticket.Symbol and
            status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: option exit filled for {symbol} at "
                f"{order_event.FillPrice}"
            )
            if not self.Portfolio[symbol].Invested:
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.expiration_guard_date = None

    def HandleUnexpectedSpyPosition(self, current_date):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            self.spy_liquidation_ticket = None
            return

        self.no_entry_date = current_date

        if (
            self.spy_liquidation_ticket is None or
            not self.IsOpen(self.spy_liquidation_ticket.Status)
        ):
            self.Debug(
                f"{self.Time}: unexpected SPY equity position detected; "
                "liquidating immediately"
            )
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def GetCurrentOptionChain(self, slice):
        try:
            chains = slice.OptionChains
            if self.option_symbol in chains:
                return chains[self.option_symbol]

            for chain in chains.Values:
                return chain
        except Exception:
            return None

        return None

    def GetHeldContract(self, slice):
        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_option:
                return contract

        return None

    def IsImmediatelyPrecedingTradingDay(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while candidate > current_date:
            if self.spy.Exchange.Hours.IsDateOpen(candidate):
