from datetime import datetime, timedelta

from AlgorithmImports import *


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bucket = None
        self._minute_bars = {}
        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal = False
        self._pending_signal_time = None
        self._latest_spy_price = None

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_fill_quantity = 0
        self._entry_fill_value = 0.0

        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._no_entry_date = None
        self._time_stop_date = None

    def OnData(self, slice: Slice):
        if self.spy in slice.Bars:
            minute_bar = slice.Bars[self.spy]
            self._latest_spy_price = float(minute_bar.Close)
            self._ingest_minute_bar(minute_bar)

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._evaluate_held_position(slice)

        if self._pending_signal:
            signal_time = self._pending_signal_time
            self._pending_signal = False
            self._pending_signal_time = None

            if signal_time is not None:
                signal_clock = signal_time.time()
                if (
                    datetime.strptime("09:45", "%H:%M").time()
                    <= signal_clock
                    <= datetime.strptime("14:30", "%H:%M").time()
                ):
                    self._try_enter(slice)

    def _ingest_minute_bar(self, bar: TradeBar):
        end = bar.EndTime
        clock = end.time()

        if clock < datetime.strptime("09:31", "%H:%M").time():
            return
        if clock > datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_end_minute = ((end.minute + 4) // 5) * 5
        if bucket_end_minute >= 60:
            bucket_end_minute = 55

        bucket_end = end.replace(
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )
        bucket_key = bucket_end

        if self._minute_bucket != bucket_key:
            if self._minute_bucket is not None:
                self._finalize_minute_bucket()

            self._minute_bucket = bucket_key
            self._minute_bars = {}

        self._minute_bars[end] = bar

        if len(self._minute_bars) == 5:
            self._finalize_minute_bucket()

    def _finalize_minute_bucket(self):
        if self._minute_bucket is None:
            return

        bucket_end = self._minute_bucket
        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]

        if all(timestamp in self._minute_bars for timestamp in expected_times):
            bars = [self._minute_bars[timestamp] for timestamp in expected_times]
            consolidated = TradeBar(
                bucket_end - timedelta(minutes=5),
                self.spy,
                bars[0].Open,
                max(float(bar.High) for bar in bars),
                min(float(bar.Low) for bar in bars),
                bars[-1].Close,
                sum(int(bar.Volume) for bar in bars),
                timedelta(minutes=5)
            )
            self._process_five_minute_bar(consolidated)

        self._minute_bucket = None
        self._minute_bars = {}

    def _process_five_minute_bar(self, bar: TradeBar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self._pending_signal = True
            self._pending_signal_time = bar.EndTime

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self._no_entry_date == current_date:
            return
        if self._entry_ticket is not None:
            return
        if self._held_symbol is not None:
            return

        spy_price = self._latest_spy_price
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: SPY price unavailable.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = []

        for chain in self._option_chains(slice):
            for contract in self._contracts(chain):
                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if float(contract.Strike) < 1.01 * spy_price:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no qualifying contract.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self._entry_symbol = selected.Symbol
        self._entry_fill_quantity = 0
        self._entry_fill_value = 0.0
        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiring {}".format(
                selected.Symbol,
                selected.Expiry.date()
            )
        )

    def _evaluate_held_position(self, slice: Slice):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        quote = self._current_option_quote(slice, self._held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self._entry_price is not None and midpoint >= 1.5 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self):
        if self._held_symbol is None:
            return

        security = self.Securities[self._held_symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self._no_entry_date = self.Time.date()
            self.Debug("Expiration handling: liquidating {}".format(self._held_symbol))
            self._submit_exit("expiration protection")
            return

        preceding_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            preceding_trading_day
        ):
            preceding_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == preceding_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
            and self._time_stop_date != preceding_trading_day
        ):
            self._time_stop_date = preceding_trading_day
            self.Debug("Time stop: liquidating {}".format(self._held_symbol))
            self._submit_exit("expiration-minus-one-day time stop")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing open exit order.")

        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self._held_symbol, reason))

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self._no_entry_date = self.Time.date()
        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                fill_quantity = abs(int(order_event.FillQuantity))
                if fill_quantity > 0:
                    self._entry_fill_quantity += fill_quantity
                    self._entry_fill_value += (
                        fill_quantity * float(order_event.FillPrice)
                    )
                    self._held_symbol = self._entry_symbol
                    self._entry_price = (
                        self._entry_fill_value / self._entry_fill_quantity
                    )

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self._held_symbol,
                            self._entry_price
                        )
                    )
                    self._entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self._entry_ticket = None
                self._entry_symbol = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self._held_symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
                self._time_stop_date = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if "assign" in message or "exercis" in message:
            self._no_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment event received.")

    def _current_option_quote(self, slice: Slice, symbol):
        for chain in self._option_chains(slice):
            for contract in self._contracts(chain):
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    @staticmethod
    def _option_chains(slice: Slice):
        chains = slice.OptionChains
        values = chains.Values if hasattr(chains, "Values") else chains

        for item in values:
            if hasattr(item, "Contracts"):
                yield item
            elif hasattr(item, "Value") and hasattr(item.Value, "Contracts"):
                yield item.Value

    @staticmethod
    def _contracts(chain):
        contracts = chain.Contracts
        return contracts.Values if hasattr(contracts, "Values") else contracts

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

