        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            preceding_trading_day
        ):
            preceding_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == preceding_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
            and self._time_stop_date != preceding_trading_day
        ):
            self._time_stop_date = preceding_trading_day
            self.Debug("Time stop: liquidating {}".format(self._held_symbol))
            self._submit_exit("expiration-minus-one-day time stop")

    def _submit_exit(self, reason):
