            self._exit_ticket.Cancel("Replacing open exit order.")

        if self._exit_ticket is not None and self._ticket_is_open(self._exit_ticket):
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self._held_symbol, reason))

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self._no_entry_date = self.Time.date()
        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                fill_quantity = abs(int(order_event.FillQuantity))
                if fill_quantity > 0:
                    self._entry_fill_quantity += fill_quantity
                    self._entry_fill_value += (
                        fill_quantity * float(order_event.FillPrice)
                    )
                    self._held_symbol = self._entry_symbol
                    self._entry_price = (
                        self._entry_fill_value / self._entry_fill_quantity
                    )

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self._held_symbol,
                            self._entry_price
                        )
                    )
                    self._entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self._entry_ticket = None
                self._entry_symbol = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self._held_symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
                self._time_stop_date = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if "assign" in message or "exercis" in message:
            self._no_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment event received.")

    def _current_option_quote(self, slice: Slice, symbol):
        for chain in self._option_chains(slice):
            for contract in self._contracts(chain):
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    @staticmethod
    def _option_chains(slice: Slice):
        chains = slice.OptionChains
        values = chains.Values if hasattr(chains, "Values") else chains

        for item in values:
            if hasattr(item, "Contracts"):
                yield item
            elif hasattr(item, "Value") and hasattr(item.Value, "Contracts"):
                yield item.Value

    @staticmethod
    def _contracts(chain):
        contracts = chain.Contracts
        return contracts.Values if hasattr(contracts, "Values") else contracts

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

