from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self._bucket_end = None
        self._bucket_bars = []
        self._bucket_valid = True

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._no_entry_today = None
        self._equity_exit_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        if self._held_symbol is not None:
            expiration_date = self._held_symbol.ID.Date.date()

            if current_date >= expiration_date:
                self._no_entry_today = current_date
                self.Debug(
                    "Expiration processing: liquidating {}".format(
                        self._held_symbol.Value
                    )
                )
                self._submit_exit("expiration")
            else:
                self._evaluate_time_stop()
                self._evaluate_profit_target(slice)

        completed_bar = self._update_five_minute_bar(slice)

        if completed_bar is not None:
            self._evaluate_entry_signal(completed_bar, slice)

    def _update_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy):
            return None

        minute_bar = slice.Bars[self.spy]
        end_time = minute_bar.EndTime.astimezone(self.TimeZone)

        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return None

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self._bucket_end != bucket_end:
            self._bucket_end = bucket_end
            self._bucket_bars = [minute_bar]
            self._bucket_valid = True
        else:
            if self._bucket_bars:
                expected_time = self._bucket_bars[-1].EndTime.astimezone(
                    self.TimeZone
                ) + timedelta(minutes=1)

                if end_time != expected_time:
                    self._bucket_valid = False

            self._bucket_bars.append(minute_bar)

        if end_time != bucket_end:
            return None

        completed = None
        if self._bucket_valid and len(self._bucket_bars) == 5:
            completed = TradeBar(
                bucket_end - timedelta(minutes=5),
                self.spy,
                self._bucket_bars[0].Open,
                max(bar.High for bar in self._bucket_bars),
                min(bar.Low for bar in self._bucket_bars),
                self._bucket_bars[-1].Close,
                sum(bar.Volume for bar in self._bucket_bars),
                timedelta(minutes=5)
            )

        self._bucket_end = None
        self._bucket_bars = []
        self._bucket_valid = True
        return completed

    def _evaluate_entry_signal(self, bar: TradeBar, slice: Slice):
        bar_end = bar.EndTime.astimezone(self.TimeZone)
        bar_time = bar_end.time()

        prior_ready = self.slow_window.IsReady
        prior_fast = None
        prior_slow = None

        if prior_ready:
            prior_fast = sum(
                self.fast_window[i] for i in range(5)
            ) / 5.0
            prior_slow = sum(
                self.slow_window[i] for i in range(20)
            ) / 20.0

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        bullish_cross = (
            prior_ready
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self._no_entry_today == self.Time.date():
            return

        if self._held_symbol is not None or self._entry_order_open():
            return

        self._select_and_enter(slice)

    def _select_and_enter(self, slice: Slice):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)
        expirations = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiration = contract.Symbol.ID.Date.date()
                if expiration >= minimum_expiration:
                    expirations.append(expiration)

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiration = min(expirations)
        spy_price = float(self.Securities[self.spy].Price)

        candidates = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                if (
                    symbol.ID.Date.date() == selected_expiration
                    and symbol.ID.OptionRight == OptionRight.Call
                    and symbol.ID.Strike >= 1.01 * spy_price
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Symbol.ID.Strike),
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol.Value,
                selected.Symbol.ID.Strike,
                selected_expiration
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_order_open():
            return

        held_contract = None
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self._held_symbol):
                held_contract = chain.Contracts[self._held_symbol]
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self):
        if self._held_symbol is None or self._exit_order_open():
            return

        expiration_date = self._held_symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiration_date)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None:
            self._exit_ticket.Cancel("Replacing exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(
                self._held_symbol.Value,
                reason
            )
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time(12, 0))
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self._no_entry_today = self.Time.date()
        self.Debug(
            "Unexpected SPY exercise or assignment position: liquidating"
        )

        if (
            self._equity_exit_ticket is None
            or self._equity_exit_ticket.Status not in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            )
        ):
            self._equity_exit_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = float(
                    self._entry_ticket.AverageFillPrice
                    or order_event.FillPrice
                )
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self._held_symbol.Value,
                        self._entry_price
                    )
                )

            if (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
                and self._held_symbol is not None
                and self.Portfolio[self._held_symbol].Quantity == 0
            ):
                self.Debug("Exit filled: {}".format(self._held_symbol.Value))
                self._held_symbol = None
                self._entry_price = None
                self._exit_ticket = None
                self._entry_ticket = None

    def OnAssignmentOrder(self, assignment_order_event):
        self._no_entry_today = self.Time.date()
        self.Debug("Unexpected option exercise or assignment received")
        self._handle_unexpected_spy_position()

