        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.entry_filled_quantity = 0

        self.expiration_blocked_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()

        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if current_date >= expiry:
                self.expiration_blocked_date = current_date
                self._submit_exit("expiration liquidation")
            else:
                previous_trading_day = self._previous_trading_day(expiry)
                if (
                    current_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            completed_bar = self._update_five_minute_bar(spy_bar)
            if completed_bar is not None:
                self._evaluate_crossover(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < datetime.strptime("09:31", "%H:%M").time():
            return None
        if local_time > datetime.strptime("16:00", "%H:%M").time():
            return None

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        if bucket_minute == 60:
            bucket_end = end_time.replace(
                hour=end_time.hour + 1, minute=0, second=0, microsecond=0
            )
        else:
            bucket_end = end_time.replace(
                minute=bucket_minute, second=0, microsecond=0
            )

        if self.current_bucket_end != bucket_end:
            completed = self._finish_bucket()
            self.current_bucket_end = bucket_end
            self.current_minutes = {}
            self.current_bars = {}
        else:
            completed = None

        self.current_minutes[minute_bar.EndTime.minute] = minute_bar.EndTime
        self.current_bars[minute_bar.EndTime.minute] = minute_bar
        return completed

    def _finish_bucket(self):
        if self.current_bucket_end is None:
            return None

        expected = set(range(self.current_bucket_end.minute - 4,
                             self.current_bucket_end.minute + 1))

        if set(self.current_bars.keys()) != expected:
            return None

        bars = [
            self.current_bars[minute]
            for minute in sorted(self.current_bars.keys())
        ]

        if any(
            bars[i].EndTime - bars[i - 1].EndTime != timedelta(minutes=1)
            for i in range(1, len(bars))
        ):
            return None

        start_time = self.current_bucket_end - timedelta(minutes=5)
        return TradeBar(
            start_time,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _evaluate_crossover(self, bar: TradeBar, slice: Slice):
        self.closes.append(bar.Close)

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            bullish_crossover
            and eligible_start <= bar_end <= eligible_end
            and self.expiration_blocked_date != self.Time.date()
            and self.held_option is None
            and not self._ticket_is_open(self.entry_ticket)
        ):
            self._attempt_entry(slice, bar.Close)

    def _attempt_entry(self, slice: Slice, spy_price: float):
        if slice.OptionChains is None:
            self.Debug("Skipped entry: no option chain.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration or call.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == nearest_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order is None:
            return

        if (
            order_event.Status == OrderStatus.Filled
            and order.Symbol == self.spy
            and getattr(order, "Type", None) == OrderType.OptionExercise
        ):
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_unexpected_equity_position()

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                prior_value = (self.entry_price or 0) * self.entry_filled_quantity
                self.entry_filled_quantity += order_event.FillQuantity
                self.entry_price = (
                    prior_value + order_event.FillPrice * order_event.FillQuantity
                ) / self.entry_filled_quantity
                self.held_option = order.Symbol
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order.Symbol, self.entry_price
                    )
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.FillQuantity != 0:
                if self.held_option is None or self.Portfolio[order.Symbol].Quantity == 0:
                    self.Debug("Exit filled: {}".format(order.Symbol))
                    self.held_option = None
                    self.entry_price = None
                    self.entry_filled_quantity = 0
                    self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        for ticket in self.Transactions.GetOpenOrders(self.spy):
            if ticket.Quantity != 0:
                return

        self.Debug("Liquidating unexpected SPY equity position.")
        self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="unexpected exercise or assignment liquidation"
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

