        self.last_trading_date = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        if self.last_trading_date != today:
            self.last_trading_date = today
            self.no_entry_date = None

        self._handle_unexpected_equity_position()
        self._process_expiration_and_time_stop(now)
        self._evaluate_profit_target(slice)

