        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.fast_value = None
        self.slow_value = None

        self.bucket_date = None
        self.bucket_start_minute = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.expiration_blocked_dates = set()
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        now = self.Time
        current_date = now.date()

        if self.held_contract is not None:
            expiry_date = self.held_contract.ID.Date.date()

            if current_date >= expiry_date:
                if self._has_option_position():
                    self.expiration_blocked_dates.add(current_date)
                    self._submit_exit("expiration processing")
            else:
                self._evaluate_profit_target(slice)
                if self._is_previous_trading_day(expiry_date, current_date):
                    if now.hour > 15 or (now.hour == 15 and now.minute >= 45):
                        self._submit_exit("expiration time stop")

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        bar_time = spy_bar.Time
        if not self._is_regular_session_minute(bar_time):
            return

        self._accept_minute_bar(spy_bar)

    def _accept_minute_bar(self, minute_bar):
        t = minute_bar.Time
        bucket_minute = 30 + ((t.minute - 30) // 5) * 5

        if self.bucket_date != t.date() or self.bucket_start_minute != bucket_minute:
            self._finalize_bucket()

            self.bucket_date = t.date()
            self.bucket_start_minute = bucket_minute
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

    def _finalize_bucket(self):
        if not self.bucket_bars:
            return

        bars = self.bucket_bars
        self.bucket_bars = []

        # Do not synthesize a five-minute bar when any minute is missing.
        if len(bars) != 5:
            self.fast_value = self.fast_value
            self.slow_value = self.slow_value
            return

        expected = bars[0].Time
        for bar in bars:
            if bar.Time != expected:
                return
            expected += timedelta(minutes=1)

        close = float(bars[-1].Close)
        self.closes.append(close)

        previous_fast = self.fast_value
        previous_slow = self.slow_value

        if len(self.closes) >= self.fast_period:
            self.fast_value = sum(
                list(self.closes)[-self.fast_period:]
            ) / self.fast_period

        if len(self.closes) >= self.slow_period:
            self.slow_value = sum(self.closes) / self.slow_period

        bar_end = bars[-1].Time + timedelta(minutes=1)
        eligible_time = (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and self.fast_value is not None
            and self.slow_value is not None
            and previous_fast <= previous_slow
            and self.fast_value > self.slow_value
        )

        if bullish_crossover and eligible_time:
            self._evaluate_entry(bars[-1])

    def _evaluate_entry(self, completed_bar):
        current_date = self.Time.date()

        if current_date in self.expiration_blocked_dates:
            return

        if self.held_contract is not None and self._has_option_position():
            return

        if self._entry_order_open():
            return

        if self._exit_order_open():
            return

        chains = list(self.CurrentSlice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        chain = None
        for candidate in chains:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days away")
            return

        selected_expiry = expirations[0]
        spy_price = float(self.Securities[self.spy_symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if not self._has_option_position() or self._exit_order_open():
            return

        contract_data = None
        for chain in slice.OptionChains:
            contract_data = chain.Contracts.get(self.held_contract.Symbol)
            if contract_data is not None:
                break

