from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(0), timedelta(days=730))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_start = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_ticket = None

        self.time_stop_date = None
        self.expiration_block_date = None
        self.assignment_liquidation_pending = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration_and_time_stop(current_date)
        self._handle_unexpected_spy_position()
        self._process_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.Time
        if local_time.hour < 9 or local_time.hour > 15:
            return
        if local_time.hour == 9 and local_time.minute < 30:
            return

        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self.bucket_bars.clear()

        self.bucket_start = bucket_start
        self.bucket_bars[local_time] = minute_bar

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(timestamp in self.bucket_bars for timestamp in expected_times):
            return

        bars = [self.bucket_bars[timestamp] for timestamp in expected_times]
        self.bucket_bars.clear()

        consolidated_open = bars[0].Open
        consolidated_high = max(bar.High for bar in bars)
        consolidated_low = min(bar.Low for bar in bars)
        consolidated_close = bars[-1].Close
        consolidated_end = bucket_start + timedelta(minutes=5)

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated_end, consolidated_close)
        self.slow.Update(consolidated_end, consolidated_close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= consolidated_end.time() <= time(14, 30)):
            return

        self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if current_date == self.expiration_block_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_order_id is not None:
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        minimum_expiration = current_date + timedelta(days=7)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no eligible expiration")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY call entry"
        )

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(f"Entry submitted: {selected.Symbol}")

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        quote = None
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    quote = contract
                    break
            if quote is not None:
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_and_time_stop(self, current_date):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiration_date = security.Symbol.ID.Date.date()

        if current_date >= expiration_date:
            self.expiration_block_date = current_date
            self._submit_exit("expiration protection")
            return

        previous_trading_date = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            previous_trading_date
        ):
            previous_trading_date -= timedelta(days=1)

        if (
            current_date == previous_trading_date and
            self.Time.time() >= time(15, 45) and
            self.time_stop_date != current_date
        ):
            self.time_stop_date = current_date
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing with required liquidation")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _order_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity == 0:
            self.assignment_liquidation_pending = False
            return

        if not self.assignment_liquidation_pending:
            self.Debug("Unexpected SPY exercise or assignment position; liquidating")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.assignment_liquidation_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill")
                self.entry_order_id = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

