        self.slow = SimpleMovingAverage(20)

        self._minute_bucket_date = None
        self._minute_bucket_end = None
        self._minute_bucket = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self._blocked_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self._blocked_date is not None and self._blocked_date != current_date:
            self._blocked_date = None

        self._handle_unexpected_spy_position(current_date)

        if self.held_symbol is not None:
            self._process_held_option(data, current_date)

        if self._entry_order_is_open():
            return

        if self.held_symbol is not None:
            return

        bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        if bar is None:
            return

        consolidated = self._add_minute_bar(bar)
        if consolidated is None:
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None
        had_ready_averages = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if not had_ready_averages or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        bar_end_time = self.Time
        eligible_time = (
            bar_end_time.hour > 9 or
            (bar_end_time.hour == 9 and bar_end_time.minute >= 45)
        ) and (
            bar_end_time.hour < 14 or
            (bar_end_time.hour == 14 and bar_end_time.minute <= 30)
        )

        if bullish_cross and eligible_time and self._blocked_date != current_date:
            self._try_enter(data, bar.Close, current_date)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"ENTRY {self.held_symbol} fill={self.entry_price:.2f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"EXIT {order_event.Symbol}")
                self.held_symbol = None
                self.entry_price = None

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _add_minute_bar(self, bar):
        local_end = self.Time.replace(second=0, microsecond=0)

        if local_end.time() < datetime.strptime("09:31", "%H:%M").time():
            return None

        if local_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return None

        minute = local_end.minute
        bucket_end_minute = minute + (5 - minute % 5)
        bucket_end = local_end.replace(minute=0) + timedelta(
            minutes=local_end.hour * 60 + bucket_end_minute
        )

        bucket_date = local_end.date()

        if (
            self._minute_bucket_date != bucket_date or
            self._minute_bucket_end != bucket_end
        ):
            self._minute_bucket_date = bucket_date
            self._minute_bucket_end = bucket_end
            self._minute_bucket = {}

        self._minute_bucket[local_end] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if local_end != bucket_end:
            return None

        if any(timestamp not in self._minute_bucket for timestamp in expected_times):
            self._minute_bucket = {}
            return None

        bars = [self._minute_bucket[timestamp] for timestamp in expected_times]

        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self._minute_bucket = {}
        return consolidated

    def _try_enter(self, data, spy_price, current_date):
        if spy_price <= 0:
            self.Debug("SKIP entry: invalid SPY price")
            return

        if not data.OptionChains:
            self.Debug("SKIP entry: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        chains = list(data.OptionChains.Values)

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("SKIP entry: no expiration at least seven days out")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("SKIP entry: no qualifying call contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"ENTRY submitted {selected.Symbol}")

    def _process_held_option(self, data, current_date):
        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._blocked_date = current_date
            self._submit_exit("expiration")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day and
            self.Time.hour == 15 and
            self.Time.minute >= 45
        ):
            self._submit_exit("expiration-eve time stop")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        midpoint = self._current_option_midpoint(data)
        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _current_option_midpoint(self, data):
        if not data.OptionChains:
            return None

        for chain in data.OptionChains.Values:
            if not chain.Contracts.ContainsKey(self.held_symbol):
                continue

            contract = chain.Contracts[self.held_symbol]
            if contract.BidPrice > 0 and contract.AskPrice > 0:
                return (contract.BidPrice + contract.AskPrice) / 2.0

        return None

    def _submit_exit(self, reason):
        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel(f"Replacing exit: {reason}")

        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"EXIT submitted {self.held_symbol}: {reason}")

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self._blocked_date = current_date
            self.Debug(
                f"UNEXPECTED exercise/assignment SPY position: liquidating {quantity}"
            )
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment")

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self._order_is_open(self.entry_ticket)
        )

    def _order_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

