        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol,
            self.consolidator
        )
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_fill_quantity = 0
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_end = bar.EndTime
        bar_start = bar_end - timedelta(minutes=5)

        if bar_start.date() != bar_end.date():
            return

        if bar_start.time() < datetime.strptime("09:30", "%H:%M").time():
            return

        if bar_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        previous_ready = self.slow_window.IsReady
        previous_fast = None
        previous_slow = None

        if previous_ready:
            previous_fast = sum(
                self.fast_window[i] for i in range(5)
            ) / 5.0
            previous_slow = sum(
                self.slow_window[i] for i in range(20)
            ) / 20.0

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        self.pending_signal = False

        if not self.slow_window.IsReady:
            return

        current_fast = sum(
            self.fast_window[i] for i in range(5)
        ) / 5.0
        current_slow = sum(
            self.slow_window[i] for i in range(20)
        ) / 20.0

        eligible_time = (
            datetime.strptime("09:45", "%H:%M").time()
            <= bar_end.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if (
            previous_ready
            and eligible_time
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.ProcessExpiration()
        self.ProcessTimeStop()
        self.ProcessProfitTarget(slice)

        if (
            self.pending_signal
            and self.no_entry_date != current_date
            and self.held_symbol is None
            and self.entry_ticket is None
        ):
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.spy_symbol not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(slice.Bars[self.spy_symbol].Close)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at the selected expiration."
            )
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.held_symbol = selected.Symbol
        self.entry_price = None
        self.entry_fill_quantity = 0

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def ProcessProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        held_contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self.held_symbol
            ),
            None
        )

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def ProcessTimeStop(self):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        expiry = self.held_symbol.ID.Date.date()
        previous_trading_day = self.GetPreviousTradingDay(expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
