from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 1000)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, self._consolidator)

        self._minute_counts = {}
        self._current_slice = None
        self._current_spy_price = None

        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._entry_order_symbol = None

        self._expiration_block_date = None
        self._equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._current_slice = slice

        if slice.Bars.ContainsKey(self.spy):
            self._current_spy_price = slice.Bars[self.spy].Close
            self._record_minute_bar(slice.Bars[self.spy])
            self._consolidator.Update(slice.Bars[self.spy])

        self._handle_unexpected_equity_position()
        self._evaluate_option_exit()

    def _record_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime
        day = local_end.date()
        total_minutes = local_end.hour * 60 + local_end.minute

        regular_start = 9 * 60 + 31
        regular_end = 16 * 60

        if total_minutes < regular_start or total_minutes > regular_end:
            return

        first_end = 9 * 60 + 35
        bucket_end_minutes = first_end + ((total_minutes - first_end + 4) // 5) * 5
        bucket_end = datetime(
            day.year,
            day.month,
            day.day,
            bucket_end_minutes // 60,
            bucket_end_minutes % 60
        )

        key = (day, bucket_end)
        if key not in self._minute_counts:
            self._minute_counts[key] = set()

        self._minute_counts[key].add(local_end)

        cutoff = day - timedelta(days=2)
        self._minute_counts = {
            k: v for k, v in self._minute_counts.items()
            if k[0] >= cutoff
        }

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        local_end = bar.EndTime
        key = (local_end.date(), local_end)

        # Require all five minute bars; never synthesize a missing interval.
        minute_endings = self._minute_counts.get(key, set())
        expected = {
            local_end - timedelta(minutes=i)
            for i in range(5)
        }

        if minute_endings != expected:
            return

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        if not bullish_cross:
            return

        local_time = local_end.time()
        if not (time(9, 45) <= local_time <= time(14, 30)):
            return

        self._try_enter_call()

    def _try_enter_call(self):
        today = self.Time.date()

        if self._expiration_block_date == today:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None:
            if self._entry_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        if self._current_slice is None or self._current_spy_price is None:
            return

        chains = list(self._current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        strike_floor = 1.01 * self._current_spy_price

        strike_candidates = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
            and c.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self._entry_order_symbol = selected.Symbol
        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY five-minute crossover call entry"
        )

    def _evaluate_option_exit(self):
        if self._held_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self._expiration_block_date = today
            self._submit_exit("Expiration processing liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time-stop liquidation")
            return

        if self._exit_ticket is not None:
            return

        quote = self._get_current_option_quote(self._held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit-target liquidation")

    def _get_current_option_quote(self, symbol):
        if self._current_slice is None:
            return None

        bid = None
        ask = None

        if self._current_slice.BidQuotes.ContainsKey(symbol):
            bid = self._current_slice.BidQuotes[symbol].Close

        if self._current_slice.AskQuotes.ContainsKey(symbol):
            ask = self._current_slice.AskQuotes[symbol].Close

        if bid is None or ask is None:
            for chain in self._current_slice.OptionChains.Values:
                if chain.Contracts.ContainsKey(symbol):
                    contract = chain.Contracts[symbol]
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    break

        if bid is None or ask is None:
            return None

        return float(bid), float(ask)

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None:
            if self._exit_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        if self._entry_ticket is not None:
            if self._entry_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self.Transactions.CancelOrder(
                    self._entry_ticket.OrderId,
                    "Cancel entry before liquidation"
                )

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity == 0:
            return

        if self._equity_liquidation_ticket is not None:
            if self._equity_liquidation_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        self.Debug("Unexpected SPY exercise or assignment position; liquidating.")
        self._equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered {} at {:.4f}".format(
                        self._held_symbol,
                        self._entry_price
                    )
                )

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    "Exited {} at {:.4f}".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self._held_symbol = None
                self._entry_price = None
                self._exit_ticket = None
                self._entry_ticket = None
                self._entry_order_symbol = None

        if order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._entry_ticket = None
                self._entry_order_symbol = None

            if (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option assignment detected.")
        elif getattr(order_event, "IsExercise", False):
            self.Debug("Unexpected option exercise detected.")

