from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.latest_spy_price = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None
        self.exit_order_id = None
        self.expiration_stop_date = None
        self.block_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        spy_bar = slice.Bars[self.spy] if self.spy in slice.Bars else None

        if spy_bar is not None:
            self.latest_spy_price = float(spy_bar.Close)
            self._process_minute_bar(spy_bar)

        self._handle_unexpected_spy_position()
        self._evaluate_held_option_exit(slice, current_date, current_time)

    def _process_minute_bar(self, bar: TradeBar):
        bar_time = bar.Time
        local_date = bar_time.date()
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            if self.bucket_date is not None and local_date != self.bucket_date:
                self._discard_bucket()
            return

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_end_minutes = ((minutes_from_open // 5) + 1) * 5
        bucket_end_hour = 9 + bucket_end_minutes // 60
        bucket_end_minute = bucket_end_minutes % 60
        bucket_end = time(bucket_end_hour, bucket_end_minute)

        if self.bucket_date != local_date or self.bucket_end != bucket_end:
            if self.bucket_date is not None:
                self._complete_bucket_if_valid()

            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if local_time == (
            datetime.combine(local_date, bucket_end) - timedelta(minutes=1)
        ).time():
            self._complete_bucket_if_valid()
            self.bucket_date = None
            self.bucket_end = None
            self.bucket_bars = []

    def _complete_bucket_if_valid(self):
        if len(self.bucket_bars) != 5:
            self._discard_bucket()
            return

        self.bucket_bars.sort(key=lambda x: x.Time)
        expected_time = self.bucket_bars[0].Time

        for bar in self.bucket_bars:
            if bar.Time != expected_time:
                self._discard_bucket()
                return
            expected_time += timedelta(minutes=1)

        five_minute_close = float(self.bucket_bars[-1].Close)
        self._update_averages_and_test_signal(five_minute_close)

    def _discard_bucket(self):
        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = []

    def _update_averages_and_test_signal(self, close):
        if len(self.closes) >= 20:
            self.previous_fast = sum(list(self.closes)[-5:]) / 5.0
            self.previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if self.previous_fast is None or self.previous_slow is None:
            return

        crossover_time = self.bucket_end
        if not (time(9, 45) <= crossover_time <= time(14, 30)):
            return

        bullish_crossover = (
            self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter_from_current_slice()

    def _try_enter_from_current_slice(self):
        current_date = self.Time.date()

        if current_date == self.block_entry_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.latest_spy_price is None:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        option_chain = self._get_current_option_chain()
        if option_chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in option_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * self.latest_spy_price

        candidates = [
            contract for contract in option_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId
        self.entry_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected.Expiry.date()} strike={selected.Strike}"
        )

    def _get_current_option_chain(self):
        for chain in self.CurrentSlice.OptionChains.Values:
            if chain.Symbol == self.spy_option.Symbol:
                return chain
        return None

    def _evaluate_held_option_exit(self, slice, current_date, current_time):
        if self.held_symbol is None:
            return

        held_security = self.Securities[self.held_symbol]
        expiry_date = held_security.Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.block_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        if (
            self.expiration_stop_date is None
            or self.expiration_stop_date != self._previous_trading_day(expiry_date)
        ):
            self.expiration_stop_date = self._previous_trading_day(expiry_date)

        if (
            current_date == self.expiration_stop_date
            and current_time >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quote = self._get_held_quote(slice)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _get_held_quote(self, slice):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation exit")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_symbol
                self.Debug(
                    f"Entry filled: {self.held_symbol} price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_symbol}")
                self.held_symbol = None
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.exit_order_id = None
                self.expiration_stop_date = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                self.exit_order_id = None

        if order_event.Status == OrderStatus.Filled:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None and order.Type == OrderType.OptionExercise:
                self.Debug("Unexpected option exercise or assignment; liquidating SPY.")
                self._liquidate_unexpected_spy_position()

    def OnAssignmentOrder(self, assignment_order):
        self.Debug("Unexpected option assignment; liquidating SPY.")
        self._liquidate_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

