        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation exit")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_symbol
                self.Debug(
                    f"Entry filled: {self.held_symbol} price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_symbol}")
                self.held_symbol = None
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.exit_order_id = None
                self.expiration_stop_date = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                self.exit_order_id = None

        if order_event.Status == OrderStatus.Filled:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None and order.Type == OrderType.OptionExercise:
                self.Debug("Unexpected option exercise or assignment; liquidating SPY.")
                self._liquidate_unexpected_spy_position()

    def OnAssignmentOrder(self, assignment_order):
        self.Debug("Unexpected option assignment; liquidating SPY.")
        self._liquidate_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

