        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.window = RollingWindow[float](20)

        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_fill_quantity = 0
        self.entry_fill_value = 0

        self.expiration_guard_date = None

        self.current_bucket_end = None
        self.current_bucket = {}

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration_guard(slice)
        self._evaluate_option_exit(slice)

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            return

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        bar_date = end_time.date()

        if end_time.time() <= time(9, 30) or end_time.time() > time(16, 0):
            self.current_bucket.clear()
            self.current_bucket_end = None
            return

        minutes_from_open = (
            (end_time.hour * 60 + end_time.minute) - (9 * 60 + 30)
        )
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = datetime.combine(
            bar_date,
            time(9, 30)
        ) + timedelta(minutes=5 * bucket_number)

        if self.current_bucket_end != bucket_end:
            self.current_bucket.clear()
            self.current_bucket_end = bucket_end

        self.current_bucket[end_time] = bar

        if end_time == bucket_end:
            if len(self.current_bucket) == 5:
                consolidated_close = bar.Close
                self._update_averages_and_check_signal(
                    bucket_end,
                    consolidated_close,
                    slice
                )

            self.current_bucket.clear()
            self.current_bucket_end = None

    def _update_averages_and_check_signal(
        self,
        bar_end: datetime,
        close: float,
        slice: Slice
    ):
        prior_fast = None
        prior_slow = None

        if self.window.IsReady:
            prior_fast = sum(
                self.window[i] for i in range(5)
            ) / 5.0
            prior_slow = sum(
                self.window[i] for i in range(20)
            ) / 20.0

        self.window.Add(float(close))

        if not self.window.IsReady:
            return

        current_fast = sum(
            self.window[i] for i in range(5)
        ) / 5.0
        current_slow = sum(
            self.window[i] for i in range(20)
        ) / 20.0

        bullish_crossover = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            local_time = bar_end.time()
            eligible = (
                time(9, 45) <= local_time <= time(14, 30)
            )

            if eligible:
                self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.entry_ticket is not None or self.held_symbol is not None:
            return

        if self.expiration_guard_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, strike {1}, expiry {2}.".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_guard(self, slice: Slice):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry:
            self.expiration_guard_date = current_date
            self._submit_exit("expiration protection")
            return

        prior_trading_day = self._previous_trading_day(expiry)

        if (
            current_date == prior_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug(
            "Exit submitted: {0}, quantity {1}, reason: {2}.".format(
                self.held_symbol,
                quantity,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.Debug("Unexpected option exercise or assignment handled.")
            if self.Portfolio[self.spy.Symbol].Quantity != 0:
                self.Liquidate(self.spy.Symbol)

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.entry_fill_quantity += float(order_event.FillQuantity)
                self.entry_fill_value += (
                    float(order_event.FillQuantity)
                    * float(order_event.FillPrice)
                )

                if self.entry_fill_quantity > 0:
                    self.entry_price = (
                        self.entry_fill_value / self.entry_fill_quantity
                    )

                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {0} at {1}.".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.held_symbol = None
            self.entry_price = None
            self.entry_fill_quantity = 0
            self.entry_fill_value = 0
            self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position liquidated: {0}.".format(
                    quantity
                )
            )
            self.Liquidate(self.spy.Symbol)

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while (
            candidate.weekday() >= 5
            or not exchange_hours.IsDateOpen(candidate)
        ):
            candidate -= timedelta(days=1)

        return candidate

