from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_date = None
        self.bucket_count = 0
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None
        self.bucket_volume = 0

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._process_held_option_exit(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return

        completed_bar = self._update_five_minute_bar(bar)
        if completed_bar is None:
            return

        bar_end = completed_bar["end"]
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.held_symbol is not None:
            return

        if self._entry_order_is_open():
            return

        if self.expiration_block_date == current_date:
            return

        if len(self.closes) >= self.slow_period:
            fast_previous = sum(self.closes[-self.fast_period - 1:-1]) / self.fast_period
            slow_previous = sum(self.closes[-self.slow_period - 1:-1]) / self.slow_period
            fast_current = sum(self.closes[-self.fast_period:]) / self.fast_period
            slow_current = sum(self.closes[-self.slow_period:]) / self.slow_period

            bullish_crossover = (
                fast_previous <= slow_previous and
                fast_current > slow_current
            )

            if bullish_crossover:
                self._try_enter(slice, completed_bar["close"])

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_unexpected_equity_position()

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_ticket.Symbol
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_price:.2f}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                if not self.Portfolio[self.exit_ticket.Symbol].Invested:
                    self.Debug(f"Exit filled: {self.exit_ticket.Symbol}")
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def _update_five_minute_bar(self, minute_bar):
        local_time = minute_bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.time() < time(9, 30) or local_time.time() > time(16, 0):
            return None

        bar_date = local_time.date()

        if self.bucket_date != bar_date:
            self.bucket_start = None
            self.bucket_date = bar_date
            self.bucket_count = 0

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute -
            (9 * 60 + 30)
        )
        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        completed = None

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            if self.bucket_count == 5:
                completed = {
                    "end": self.bucket_start + timedelta(minutes=5),
                    "close": self.bucket_close
                }
                self.closes.append(float(self.bucket_close))
                if len(self.closes) > self.slow_period + 1:
                    self.closes.pop(0)

            self.bucket_start = None
            self.bucket_count = 0

        if self.bucket_start is None:
            self.bucket_start = bucket_start
            self.bucket_count = 0
            self.bucket_open = minute_bar.Open
            self.bucket_high = minute_bar.High
            self.bucket_low = minute_bar.Low
            self.bucket_close = minute_bar.Close
            self.bucket_volume = minute_bar.Volume
        else:
            self.bucket_high = max(self.bucket_high, minute_bar.High)
            self.bucket_low = min(self.bucket_low, minute_bar.Low)
            self.bucket_close = minute_bar.Close
            self.bucket_volume += minute_bar.Volume

        self.bucket_count += 1
        return completed

    def _try_enter(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Entry skipped: no option chain.")
            return

        current_date = self.Time.date()
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()

