        if self.current_bar_date != session_date:
            self.minute_bars.clear()
            self.current_bar_date = session_date

        if end_time < time(9, 31) or end_time > time(16, 0):
            return

        if end_time.minute % 5 != 0:
            self.minute_bars[end] = bar
            return

        expected_times = [
            end - timedelta(minutes=offset)
            for offset in range(4, -1, -1)
        ]

        bars = [self.minute_bars.get(minute_end) for minute_end in expected_times]
        bars.append(bar)

        for minute_end in expected_times:
            self.minute_bars.pop(minute_end, None)

        if any(item is None for item in bars):
            return

        first = bars[0]
        consolidated = TradeBar(
            end - timedelta(minutes=5),
            self.spy,
            first.Open,
            max(item.High for item in bars),
            min(item.Low for item in bars),
            bar.Close,
            sum(item.Volume for item in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated)

    def _on_five_minute_bar(self, bar: TradeBar):
        bar_end = bar.EndTime
        end_time = bar_end.time()

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_crossover and time(9, 45) <= end_time <= time(14, 30):
            self.pending_signal = bar_end

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if today in self.blocked_dates:
            return

        if self.entry_ticket is not None and not self._order_closed(self.entry_ticket):
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: SPY option chain unavailable.")
            return

        minimum_expiry = today + timedelta(days=7)
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiry_date = min(contract.Expiry.date() for contract in eligible)
        spy_price = self.Securities[self.spy].Price
        minimum_strike = 1.01 * spy_price

        contracts = [
            contract for contract in eligible
            if contract.Expiry.date() == expiry_date
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} at strike {selected.Strike}"
        )

    def _manage_open_option(self, slice: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.blocked_dates.add(today)
            self._submit_option_exit("Expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("Expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = self._get_current_contract(slice, self.entry_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_order()
            self._submit_option_exit("50 percent profit target")

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_option_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        quantity = int(self.Portfolio[self.entry_symbol].Quantity)
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._order_closed(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.entry_symbol} ({reason})")

    def _cancel_exit_order(self):
        if self.exit_ticket is not None and not self._order_closed(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by profit-target exit")
            self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        date_value -= timedelta(days=1)

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def _handle_unexpected_spy_position(self):
        quantity = int(self.Portfolio[self.spy].Quantity)
        if quantity == 0:
            return

        today = self.Time.date()
        if today in self.equity_liquidation_dates:
            return

        self.equity_liquidation_dates.add(today)
        self.blocked_dates.add(today)
        self.Debug("Unexpected SPY exercise or assignment detected; liquidating equity.")
        self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise or assignment")

    def _order_closed(self, ticket):
        return ticket.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}")
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        if order_event.Symbol == self.spy and order_event.Status == OrderStatus.Filled:
            self.Debug("Unexpected SPY equity order fill handled.")

