from AlgorithmImports import *
from datetime import timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(7, 365)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.bucket_end = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_fill_quantity = 0
        self.entry_fill_notional = 0.0

        self.expiration_processed_dates = set()
        self.time_stop_dates = set()
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self._process_option_expiration():
            return

        spy_bar = None
        if self.spy in slice.Bars:
            spy_bar = slice.Bars[self.spy]
            self._process_minute_bar(spy_bar)

        self._evaluate_exit(slice)

        if spy_bar is not None:
            self._handle_entry_signal(slice, spy_bar)

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute_end = end_time.replace(second=0, microsecond=0)
        minutes_from_first_close = (
            minute_end.hour * 60 + minute_end.minute
        ) - (9 * 60 + 35)

        if minutes_from_first_close < 0:
            return

        bucket_number = minutes_from_first_close // 5
        bucket_end = end_time.replace(
            hour=9,
            minute=35,
            second=0,
            microsecond=0
        ) + timedelta(minutes=5 * bucket_number)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finalize_bucket()

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_closes = {}

        self.bucket_closes[minute_end] = float(bar.Close)

        if minute_end == bucket_end:
            self._finalize_bucket()

    def _finalize_bucket(self):
        if self.bucket_end is None:
            return

        expected_times = {
            self.bucket_end - timedelta(minutes=offset)
            for offset in range(5)
        }

        if set(self.bucket_closes.keys()) == expected_times:
            close = self.bucket_closes[self.bucket_end]
            was_ready = self.slow_window.IsReady

            previous_fast = None
            previous_slow = None

            if was_ready:
                previous_fast = self._window_average(self.fast_window)
                previous_slow = self._window_average(self.slow_window)

            self.fast_window.Add(close)
            self.slow_window.Add(close)

            if was_ready and self.slow_window.IsReady:
                current_fast = self._window_average(self.fast_window)
                current_slow = self._window_average(self.slow_window)

                bullish_crossover = (
                    previous_fast <= previous_slow
                    and current_fast > current_slow
                )

                if bullish_crossover:
                    bar_time = self.bucket_end.time()
                    if time(9, 45) <= bar_time <= time(14, 30):
                        self._pending_entry_signal = True
                        self._pending_entry_time = self.bucket_end

        self.bucket_end = None
        self.bucket_closes = {}

    def _window_average(self, window):
        total = 0.0
        for i in range(window.Count):
            total += float(window[i])
        return total / window.Count

    def _handle_entry_signal(self, slice: Slice, spy_bar: TradeBar):
        if not getattr(self, "_pending_entry_signal", False):
            return

        signal_time = self._pending_entry_time
        self._pending_entry_signal = False

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.held_symbol is not None:
            return

        current_price = float(spy_bar.Close)
        current_date = self.Time.date()

        chain = None
        try:
            if self.option_symbol in slice.OptionChains:
                chain = slice.OptionChains[self.option_symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible
        )

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= current_price * 1.01
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_fill_quantity = 0
        self.entry_fill_notional = 0.0
        self.entry_price = None

        self.Debug(
            "Entry submitted: {} at {}".format(
                selected.Symbol, signal_time
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        current_date = self.Time.date()
        held_security = self.Securities[self.held_symbol]
        expiry_date = held_security.Symbol.ID.Date.date()

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
            and current_date not in self.time_stop_dates
        ):
            self.time_stop_dates.add(current_date)
            self._submit_exit("expiration time stop")
            return

        contract = None
        try:
            if self.held_symbol in slice.OptionChains:
                for candidate in slice.OptionChains[self.held_symbol]:
                    if candidate.Symbol == self.held_symbol:
                        contract = candidate
                        break
        except Exception:
            contract = None

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(self.held_symbol, reason)
        )

    def _process_option_expiration(self):
        if self.held_symbol is None:
            return False

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.expiration_processed_dates.add(current_date)
            self._submit_exit("unexpected expiration exposure")
            return True

        return False

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled
                ):
                    fill_quantity = abs(order_event.FillQuantity)
                    self.entry_fill_quantity += fill_quantity
                    self.entry_fill_notional += (
                        fill_quantity * float(order_event.FillPrice)
                    )

                    self.held_symbol = self.entry_ticket.Symbol
                    if self.entry_fill_quantity > 0:
                        self.entry_price = (
                            self.entry_fill_notional
                            / self.entry_fill_quantity
                        )

                    if order_event.Status == OrderStatus.Filled:
                        self.entry_ticket = None
                        self.Debug(
                            "Entry filled: {} at {:.4f}".format(
                                self.held_symbol, self.entry_price
                            )
                        )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.entry_ticket = None
                    self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} at {:.4f}".format(
                            self.held_symbol, float(order_event.FillPrice)
                        )
                    )
                    if (
                        self.held_symbol is not None
                        and self.Portfolio[self.held_symbol].Quantity == 0
                    ):
                        self.held_symbol = None
                        self.entry_price = None
                        self.entry_fill_quantity = 0
                        self.entry_fill_notional = 0.0
                        self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment handled.")
            self._handle_unexpected_spy_position()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment handled.")
        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.spy_liquidation_ticket is not None
            and self._ticket_is_open(self.spy_liquidation_ticket)
        ):
            return

        self.spy_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Liquidate unexpected exercise or assignment"
        )
        self.Debug(
            "Liquidating unexpected SPY position: {} shares.".format(quantity)
        )

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

