from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._current_slice = None
        self._bucket_start = None
        self._bucket_closes = {}

        self._held_option = None
        self._entry_order_id = None
        self._entry_price = None
        self._exit_order_id = None
        self._expiration_block_date = None
        self._time_stop_done = False

    def OnData(self, slice: Slice):
        self._current_slice = slice
        current_date = self.Time.date()

        if self._held_option is not None:
            expiry_date = self._held_option.ID.Date.date()

            if current_date >= expiry_date:
                self._expiration_block_date = current_date
                self._SubmitExit("expiration")
            else:
                previous_trading_day = self._PreviousTradingDay(expiry_date)
                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self._SubmitExit("time stop")
                else:
                    self._EvaluateProfitTarget(slice)

        if self.spy_symbol in slice.Bars:
            self._UpdateFiveMinuteBar(slice.Bars[self.spy_symbol])

    def _UpdateFiveMinuteBar(self, minute_bar: TradeBar):
        # Slice time is the minute bar's end time in the algorithm time zone.
        minute_start = self.Time.replace(second=0, microsecond=0) - timedelta(minutes=1)
        session_start = time(9, 30)
        session_end = time(16, 0)

        if minute_start.time() < session_start or minute_start.time() >= session_end:
            self._bucket_start = None
            self._bucket_closes = {}
            return

        minutes_from_open = int(
            (minute_start - minute_start.replace(
                hour=9, minute=30, second=0, microsecond=0
            )).total_seconds() // 60
        )
        bucket_start = minute_start.replace(
            hour=9,
            minute=30 + (minutes_from_open // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._FinalizeFiveMinuteBar()

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_closes = {}

        self._bucket_closes[minute_start] = float(minute_bar.Close)

    def _FinalizeFiveMinuteBar(self):
        if self._bucket_start is None:
            return

        expected = {
            self._bucket_start + timedelta(minutes=i)
            for i in range(5)
        }

        if set(self._bucket_closes.keys()) != expected:
            self._bucket_start = None
            self._bucket_closes = {}
            return

        end_time = self._bucket_start + timedelta(minutes=5)
        close = self._bucket_closes[
            self._bucket_start + timedelta(minutes=4)
        ]

        self.fast.Update(IndicatorDataPoint(end_time, close))
        self.slow.Update(IndicatorDataPoint(end_time, close))

        if self.fast.IsReady and self.slow.IsReady:
            previous_fast = float(self.fast[1].Value)
            previous_slow = float(self.slow[1].Value)
            current_fast = float(self.fast.Current.Value)
            current_slow = float(self.slow.Current.Value)

            eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

            if (
                eligible_time
                and previous_fast <= previous_slow
                and current_fast > current_slow
            ):
                self._TryEnter()

        self._bucket_start = None
        self._bucket_closes = {}

    def _TryEnter(self):
        if self._expiration_block_date == self.Time.date():
            return

        if self._held_option is not None or self._entry_order_id is not None:
            return

        if self._current_slice is None or self.option_symbol not in self._current_slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        spy_price = float(self.Securities[self.spy_symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = self._current_slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Skipped entry: no qualifying call expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in calls
        )

        strike_floor = spy_price * 1.01
        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self._entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _EvaluateProfitTarget(self, slice: Slice):
        if self._held_option is None or self._entry_price is None:
            return

        if self._exit_order_id is not None:
            return

        if self._held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self._held_option]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._SubmitExit("profit target")

    def _SubmitExit(self, reason):
        if self._held_option is None or self._exit_order_id is not None:
            return

        quantity = int(self.Portfolio[self._held_option].Quantity)
        if quantity <= 0:
            return

        self._CancelOtherExitOrders()
        order = self.MarketOrder(self._held_option, -quantity)
        self._exit_order_id = order.OrderId
        self.Debug("Exit submitted ({}): {}".format(reason, self._held_option))

    def _CancelOtherExitOrders(self):
        if self._exit_order_id is not None:
            self.Transactions.CancelOrder(self._exit_order_id)
            self._exit_order_id = None

    def _PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order_id is not None
            and order_event.OrderId == self._entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
