        bucket_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(minute=0, second=0, microsecond=0)
        bucket_end += timedelta(minutes=bucket_minute)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_bucket_closes = []
            self.current_bucket_times = []

        self.current_bucket_closes.append(float(bar.Close))
        self.current_bucket_times.append(end_time)

        if minute % 5 != 0:
            return

        expected_times = [
            bucket_end - timedelta(minutes=offset)
            for offset in range(4, -1, -1)
        ]

        valid_bar = (
            len(self.current_bucket_times) == 5
            and self.current_bucket_times == expected_times
        )

        if valid_bar:
            self._process_five_minute_close(
                bucket_end,
                self.current_bucket_closes[-1],
                slice
            )

        self.current_bucket_closes = []
        self.current_bucket_times = []

    def _process_five_minute_close(self, bar_end, close, slice):
        previous_fast = self.fast_window.Current.Value if self.fast_window.IsReady else None
        previous_slow = self.slow_window.Current.Value if self.slow_window.IsReady else None

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(
            self.fast_window[i] for i in range(self.fast_window.Count)
        ) / self.fast_window.Count

        current_slow = sum(
            self.slow_window[i] for i in range(self.slow_window.Count)
        ) / self.slow_window.Count

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

