        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiry = expirations[0]
        target_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= target_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no eligible call at selected expiration."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} strike {:.2f}, expiration {}.".format(
                selected.Symbol,
                float(selected.Strike),
                selected.Expiry.date()
            )
        )

