        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_contract))

    def _is_trading_day_before_expiration(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        for offset in range(1, 8):
            candidate = current_date + timedelta(days=offset)
            candidate_dt = datetime(
                candidate.year, candidate.month, candidate.day, 12, 0
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate_dt):
                return candidate == expiry_date

        return False

