        self.Debug("Unexpected SPY exercise/assignment handled; equity liquidated.")

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid, OrderStatus.Filled]:
            if orderEvent.OrderId == self.entry_order_id:
                if orderEvent.Status == OrderStatus.Filled:
                    self.held_contract = orderEvent.Symbol
                    self.entry_price = float(orderEvent.FillPrice)
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self.held_contract,
                            self.entry_price
                        )
                    )
                else:
                    self.Debug("Entry order did not fill: {}".format(orderEvent.Symbol))
                self.entry_order_id = None

            elif orderEvent.OrderId == self.exit_order_id:
                if orderEvent.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}".format(orderEvent.Symbol))
                    if self.Portfolio[orderEvent.Symbol].Quantity == 0:
                        self.held_contract = None
                        self.entry_price = None
                self.exit_order_id = None

            elif orderEvent.OrderId == self.equity_liquidation_order_id:
                if orderEvent.Status == OrderStatus.Filled:
                    self.Debug("Unexpected SPY equity liquidation filled.")
                self.equity_liquidation_order_id = None

        self._liquidate_unexpected_equity()

