from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import deque


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = False
        self.last_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_date != current_date:
            self.last_date = current_date
            self.no_entry_today = False

        if self.held_symbol is not None:
            expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_today = True
                self._submit_exit("expiration-date liquidation")
            else:
                self._evaluate_profit_target(slice)
                self._evaluate_time_stop(current_date, expiry)

        if self.Portfolio[self.spy].Invested and self.held_symbol is None:
            self.no_entry_today = True
            self.Debug("Unexpected SPY equity position detected; liquidating immediately.")
            self.Liquidate(self.spy, "unexpected exercise or assignment")

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        minute = end_time.hour * 60 + end_time.minute

        session_start = 9 * 60 + 31
        session_end = 16 * 60

        if minute < session_start or minute > session_end:
            return

        bucket_end_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            end_time.hour,
            0,
            0
        ) + timedelta(minutes=bucket_end_minute)

        if self.minute_bucket is not None and bucket_end != self.minute_bucket:
            self._flush_minute_bucket(slice)

        if self.minute_bucket is None:
            self.minute_bucket = bucket_end
            self.minute_bars = {}

        self.minute_bars[end_time] = bar

        if end_time.minute % 5 == 0:
            self._flush_minute_bucket(slice)

    def _flush_minute_bucket(self, slice: Slice):
        if self.minute_bucket is None:
            return

        bucket_end = self.minute_bucket
        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(1, 6)
        ]

        bars = [self.minute_bars.get(t) for t in expected_times]
        self.minute_bucket = None
        self.minute_bars = {}

        if any(bar is None for bar in bars):
            return

        bars.reverse()
        consolidated_close = bars[-1].Close
        self._update_averages(consolidated_close, bucket_end, slice)

    def _update_averages(self, close, bar_end, slice: Slice):
        if len(self.fast_closes) >= 20:
            prior_fast = sum(list(self.fast_closes)[-5:]) / 5.0
            prior_slow = sum(self.fast_closes) / 20.0
        else:
            prior_fast = None
            prior_slow = None

        self.fast_closes.append(float(close))

        if len(self.fast_closes) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        current_fast = sum(list(self.fast_closes)[-5:]) / 5.0
        current_slow = sum(self.fast_closes) / 20.0

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (9 * 60 + 45 <= bar_end.hour * 60 + bar_end.minute <= 14 * 60 + 30):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price):
        if self.no_entry_today or self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiration {selected_expiry}, strike {selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        bid = None
        ask = None

        quote_bar = slice.QuoteBars.get(self.held_symbol)
        if quote_bar is not None:
            bid = float(quote_bar.Bid.Close)
            ask = float(quote_bar.Ask.Close)

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            chain = slice.OptionChains.get(self.option_symbol)
            if chain is not None:
                for contract in chain:
                    if contract.Symbol == self.held_symbol:
                        bid = float(contract.BidPrice)
                        ask = float(contract.AskPrice)
                        break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _evaluate_time_stop(self, current_date, expiry_date):
        if self.Time.hour * 60 + self.Time.minute < 15 * 60 + 45:
            return

        next_trading_date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while next_trading_date < expiry_date:
            probe = datetime(
                next_trading_date.year,
                next_trading_date.month,
                next_trading_date.day
            )
            if exchange_hours.IsDateOpen(probe):
                break
            next_trading_date += timedelta(days=1)

        if next_trading_date == expiry_date:
            self._submit_exit("expiration-eve time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}; reason: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                )
            ):
                self.entry_ticket = None
            return

        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_today = True
            self.Debug("Unexpected option exercise or assignment detected.")

            if self.Portfolio[self.spy].Quantity != 0:
                self.Liquidate(self.spy, "unexpected exercise or assignment")
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if self.entry_price is None and order_event.FillPrice > 0:
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = order_event.Symbol
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_price:.4f}"
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_ticket = None

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

